  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('ENG-0336', 'English', 'Reading and figurative language', 'Figures of speech', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 1.3', '"Time is a thief that steals our youth." This line uses:', '["a simile", "onomatopoeia", "a metaphor", "alliteration"]', 2, 'Time is called a thief directly, without ''like'' or ''as'', so it is a metaphor.', '{"0": "A simile would need ''like'' or ''as''.", "1": "There is no word imitating a sound.", "3": "The line is not built on repeated opening sounds."}'),
  ('ENG-0337', 'English', 'Reading and figurative language', 'Figures of speech', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 1.3', '"The old car coughed and groaned as it climbed the hill." This line mainly uses:', '["hyperbole", "a simile", "an oxymoron", "personification"]', 3, 'The car is given human actions (coughing and groaning), which is personification.', '{"0": "Nothing is exaggerated for effect.", "1": "There is no comparison using ''like'' or ''as''.", "2": "No contradictory words are paired."}'),
  ('ENG-0338', 'English', 'Reading and figurative language', 'Figures of speech', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 1.3', '"This bag weighs a ton!" This line uses:', '["hyperbole", "a metaphor", "personification", "irony"]', 0, 'A bag cannot really weigh a ton; this deliberate exaggeration is hyperbole.', '{"1": "The bag is not being called something else.", "2": "The bag is not given human qualities.", "3": "The speaker means the bag is heavy, so this is not irony."}'),
  ('ENG-0339', 'English', 'Reading and figurative language', 'Figures of speech', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 1.3', '"The doctor was as cool as a cucumber during the emergency." This line uses:', '["a metaphor", "a simile", "an oxymoron", "onomatopoeia"]', 1, 'The doctor''s calmness is compared to a cucumber using ''as ... as'', so it is a simile.', '{"0": "A metaphor would not use ''as''.", "2": "No opposite words are paired.", "3": "No word imitates a sound."}'),
  ('ENG-0340', 'English', 'Pronoun-antecedent agreement', 'Indefinite pronouns as antecedents', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.3', 'Choose the option that correctly fills the blank:
Each of the mothers brought ______ baby to the clinic for vaccination.', '["its", "hers", "her", "our"]', 2, '''Each'' is singular and refers to mothers, so the pronoun is the singular feminine possessive ''her''.', '{"0": "''Its'' is for things or animals, not mothers.", "1": "''Hers'' stands alone and cannot come before a noun.", "3": "''Our'' would include the speaker."}'),
  ('ENG-0341', 'English', 'Pronoun-antecedent agreement', 'Collective nouns as antecedents', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.3', 'Choose the option that correctly fills the blank:
The committee announced ______ decision after a long meeting.', '["it''s", "his", "her", "its"]', 3, 'A committee acting as one body is treated as a single thing, so the possessive is ''its''.', '{"0": "''It''s'' means ''it is''.", "1": "A committee is not a male person.", "2": "A committee is not a female person."}'),
  ('ENG-0342', 'English', 'Pronoun-antecedent agreement', 'Collective nouns as antecedents', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.3', 'Choose the option that correctly fills the blank:
The jury could not agree; ______ argued for hours among themselves.', '["they", "it", "he", "its"]', 0, 'When members of a group act as individuals (disagreeing among themselves), the plural ''they'' is used.', '{"1": "''It'' treats the jury as one unit, but its members are acting separately.", "2": "The jury is a group, not one man.", "3": "''Its'' is possessive and cannot be the subject."}'),
  ('ENG-0343', 'English', 'Pronoun-antecedent agreement', 'Indefinite pronouns as antecedents', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.3', 'Choose the option that correctly fills the blank:
Neither of the girls has finished ______ homework.', '["their", "her", "hers", "them"]', 1, '''Neither'' is singular and refers to girls, so the pronoun is ''her''.', '{"0": "''Their'' is plural; ''neither'' is singular.", "2": "''Hers'' cannot come before a noun.", "3": "''Them'' is an object pronoun, not a possessive."}'),
  ('ENG-0344', 'English', 'Pronoun-antecedent agreement', 'Relative pronouns', 'easy', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.3', 'Choose the option that correctly fills the blank:
The patients ______ were admitted yesterday have been discharged.', '["which", "whose", "who", "whom"]', 2, 'The relative pronoun refers to people and is the subject of ''were admitted'', so ''who''.', '{"0": "''Which'' is for things.", "1": "''Whose'' shows possession.", "3": "''Whom'' is an object form; here it is the subject."}'),
  ('ENG-0345', 'English', 'Pronoun-antecedent agreement', 'Relative pronouns', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.3', 'Choose the option that correctly fills the blank:
This is the doctor ______ I told you about.', '["which", "whose", "what", "whom"]', 3, 'The pronoun refers to a person and is the object of the preposition ''about'', so the formal form is ''whom''.', '{"0": "''Which'' is for things.", "1": "''Whose'' shows possession.", "2": "''What'' cannot introduce a relative clause after a noun."}'),
  ('ENG-0346', 'English', 'Pronoun-antecedent agreement', 'Pronoun case', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.3', 'Choose the option that correctly fills the blank:
Sana and ______ went to the library together.', '["I", "me", "myself", "mine"]', 0, 'The pronoun is part of the subject, so the subject form ''I'' is needed (test: ''I went'').', '{"1": "''Me went'' is wrong; ''me'' is an object form.", "2": "Reflexive ''myself'' cannot be a subject on its own.", "3": "''Mine'' is possessive."}'),
  ('ENG-0347', 'English', 'Pronoun-antecedent agreement', 'Pronoun case', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.3', 'Choose the option that correctly fills the blank:
The teacher gave the prize to Ali and ______.', '["I", "me", "myself", "mine"]', 1, 'The pronoun follows the preposition ''to'', so the object form ''me'' is needed (test: ''gave the prize to me'').', '{"0": "''To I'' is wrong; ''I'' is a subject form.", "2": "''Myself'' is used only when the subject is also ''I''.", "3": "''Mine'' is possessive."}'),
  ('ENG-0348', 'English', 'Pronoun-antecedent agreement', 'Consistency of person', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.3', 'Which sentence is grammatically correct?', '["If a student wants to pass, you must work hard.", "If a student wants to pass, we must work hard.", "If a student wants to pass, he or she must work hard.", "If students wants to pass, he must work hard."]', 2, 'The pronoun ''he or she'' matches the singular antecedent ''a student'' and keeps the same person.', '{"0": "Switching from ''a student'' to ''you'' is a shift in person.", "1": "Switching to ''we'' is a shift in person.", "3": "''Students wants'' breaks agreement, and ''he'' does not match plural ''students''."}'),
  ('ENG-0349', 'English', 'Pronoun-antecedent agreement', 'Clear pronoun reference', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.3', 'Which sentence has a CLEAR pronoun reference?', '["When the bottle fell on the glass, it broke.", "Hina told her mother that she needed rest.", "The doctor spoke to the patient after he had eaten.", "When the bottle fell on the glass, the bottle broke."]', 3, 'Repeating ''the bottle'' removes any doubt about what broke.', '{"0": "''It'' could be the bottle or the glass.", "1": "''She'' could be Hina or her mother.", "2": "''He'' could be the doctor or the patient."}'),
  ('ENG-0350', 'English', 'Tenses', 'Simple present', 'easy', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.4', 'Choose the option that correctly fills the blank:
The train ______ at 6 p.m. every evening.', '["leaves", "is leaving", "left", "has left"]', 0, 'A fixed timetable or regular event takes the simple present.', '{"1": "Present continuous is for an action happening now, not a daily timetable.", "2": "''Every evening'' shows a habit, not one past event.", "3": "Present perfect does not describe a daily schedule."}'),
  ('ENG-0351', 'English', 'Tenses', 'Past continuous', 'easy', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.4', 'Choose the option that correctly fills the blank:
While she ______ dinner, the phone rang.', '["cooked", "was cooking", "is cooking", "had cooked"]', 1, 'A longer action in progress interrupted by a shorter past action takes the past continuous.', '{"0": "Simple past would make cooking a completed short action.", "2": "The time is past (''rang''), so present continuous is wrong.", "3": "Past perfect would mean dinner was already finished before the call."}'),
  ('ENG-0352', 'English', 'Tenses', 'Present perfect', 'easy', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.4', 'Choose the option that correctly fills the blank:
I ______ this film three times already.', '["saw", "see", "have seen", "had seen"]', 2, '''Already'' with a number of times up to now takes the present perfect.', '{"0": "Simple past does not go with ''already'' for experience up to now.", "1": "Simple present does not show completed viewings.", "3": "Past perfect needs a later past point, which is not given."}'),
  ('ENG-0353', 'English', 'Tenses', 'Present perfect continuous', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.4', 'Choose the option that correctly fills the blank:
She ______ for the exam since morning, so she is very tired.', '["studies", "studied", "is studying", "has been studying"]', 3, 'An action that started in the past and continues up to now, with ''since'', takes the present perfect continuous.', '{"0": "Simple present does not go with ''since''.", "1": "Simple past does not connect to the present tiredness.", "2": "Present continuous does not go with ''since''."}'),
  ('ENG-0354', 'English', 'Tenses', 'Past perfect', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.4', 'Choose the option that correctly fills the blank:
By the time the ambulance arrived, the patient ______ consciousness.', '["had lost", "lost", "has lost", "loses"]', 0, 'An action completed before another past action takes the past perfect.', '{"1": "Simple past does not show it happened first.", "2": "Present perfect does not fit a past time frame.", "3": "Simple present is wrong for a past event."}'),
  ('ENG-0355', 'English', 'Tenses', 'Future continuous', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.4', 'Choose the option that correctly fills the blank:
Don''t call me at 9 tonight; I ______ my favourite programme.', '["will watch", "will be watching", "watch", "watched"]', 1, 'An action that will be in progress at a particular future time takes the future continuous.', '{"0": "Simple future does not show the action in progress at 9.", "2": "Simple present does not show a future action in progress.", "3": "Simple past is wrong for tonight."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10, s.column11,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('ENG-0356', 'English', 'Tenses', 'Conditionals', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.4', 'Choose the option that correctly fills the blank:
If I had known about the test, I ______ harder.', '["would study", "will study", "would have studied", "had studied"]', 2, 'A third conditional (if + past perfect) takes ''would have'' + past participle in the main clause.', '{"0": "''Would study'' belongs to the second conditional.", "1": "''Will study'' belongs to the first conditional.", "3": "''Had studied'' cannot be the main-clause verb here."}'),
  ('ENG-0357', 'English', 'Tenses', 'Conditionals', 'easy', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.4', 'Choose the option that correctly fills the blank:
If you ______ the red button, the alarm will ring.', '["pressed", "will press", "had pressed", "press"]', 3, 'In a first conditional, the if-clause takes the simple present and the main clause takes ''will''.', '{"0": "''Pressed'' belongs to the second conditional.", "1": "''Will'' is not used in the if-clause.", "2": "''Had pressed'' belongs to the third conditional."}'),
  ('ENG-0358', 'English', 'Tenses', 'Simple past vs present perfect', 'easy', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.4', 'Choose the option that correctly fills the blank:
She ______ to Karachi last month for her cousin''s wedding.', '["went", "has gone", "goes", "had been going"]', 0, '''Last month'' is a finished past time, which takes the simple past.', '{"1": "Present perfect cannot be used with a finished past time like ''last month''.", "2": "Simple present does not fit a past event.", "3": "Past perfect continuous is not needed for one completed trip."}'),
  ('ENG-0359', 'English', 'Tenses', 'Stative verbs', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.4', 'Choose the option that correctly fills the blank:
This soup ______ delicious.', '["is tasting", "tastes", "has been tasting", "tasting"]', 1, '''Taste'' describing a quality is a stative verb, so it takes the simple present, not the continuous.', '{"0": "Stative verbs are not normally used in the continuous form.", "2": "The perfect continuous is not used for a quality.", "3": "A sentence needs a finite verb; ''tasting'' alone is not one."}'),
  ('ENG-0360', 'English', 'Tenses', 'Future perfect continuous', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.4', 'Choose the option that correctly fills the blank:
By the end of this year, they ______ in this city for ten years.', '["will live", "are living", "will have been living", "lived"]', 2, 'Duration continuing up to a point in the future takes the future perfect continuous.', '{"0": "Simple future does not show duration up to a future point.", "1": "Present continuous does not match ''by the end of this year ... for ten years''.", "3": "Simple past is wrong for a future point."}'),
  ('ENG-0361', 'English', 'Infinitives and gerunds', 'Verbs followed by a gerund', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.6', 'Choose the option that correctly fills the blank:
He admitted ______ the money from the drawer.', '["to take", "take", "for taking", "taking"]', 3, '''Admit'' is followed by a gerund.', '{"0": "''Admit to take'' is wrong; ''admit'' takes a gerund.", "1": "A bare verb cannot follow ''admitted'' here.", "2": "''Admit for'' is not an English pattern."}'),
  ('ENG-0362', 'English', 'Infinitives and gerunds', 'Verbs followed by an infinitive', 'easy', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.5', 'Choose the option that correctly fills the blank:
The doctor advised him ______ more water.', '["to drink", "drinking", "drink", "drank"]', 0, '''Advise + object'' is followed by a to-infinitive.', '{"1": "After ''advise + object'', a gerund is not used.", "2": "A bare infinitive is not used after ''advise''.", "3": "A past tense form cannot follow here."}'),
  ('ENG-0363', 'English', 'Infinitives and gerunds', 'Verbs followed by an infinitive', 'easy', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.5', 'Choose the option that correctly fills the blank:
She hopes ______ a cardiologist one day.', '["becoming", "to become", "become", "to becoming"]', 1, '''Hope'' is followed by a to-infinitive.', '{"0": "''Hope'' does not take a gerund.", "2": "A bare infinitive cannot follow ''hope''.", "3": "''To becoming'' mixes the two forms."}'),
  ('ENG-0364', 'English', 'Infinitives and gerunds', 'Verbs followed by a gerund', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.6', 'Choose the option that correctly fills the blank:
I can''t help ______ when I watch that comedy.', '["to laugh", "laugh", "laughing", "laughed"]', 2, '''Can''t help'' (cannot stop oneself) is followed by a gerund.', '{"0": "''Can''t help to'' is not standard with this meaning.", "1": "A bare verb cannot follow ''help'' here.", "3": "A past form cannot follow ''help''."}'),
  ('ENG-0365', 'English', 'Infinitives and gerunds', 'Bare infinitive', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.5', 'Choose the option that correctly fills the blank:
You had better ______ a doctor about that cough.', '["to see", "seeing", "saw", "see"]', 3, '''Had better'' is followed by a bare infinitive (no ''to'').', '{"0": "''Had better to'' is wrong.", "1": "A gerund cannot follow ''had better''.", "2": "A past form cannot follow ''had better''."}'),
  ('ENG-0366', 'English', 'Infinitives and gerunds', 'Gerund after a preposition', 'easy', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.6', 'Choose the option that correctly fills the blank:
He is interested in ______ surgery.', '["studying", "to study", "study", "studied"]', 0, 'A preposition (''in'') is followed by a gerund.', '{"1": "A to-infinitive cannot follow a preposition.", "2": "A bare verb cannot follow a preposition.", "3": "A past form cannot follow a preposition here."}'),
  ('ENG-0367', 'English', 'Infinitives and gerunds', 'Change of meaning: gerund or infinitive', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.6', 'Choose the option that correctly fills the blank:
I will never forget ______ the Himalayas for the first time.', '["to see", "seeing", "see", "to seeing"]', 1, '''Forget + gerund'' refers to a memory of something already done.', '{"0": "''Forget to see'' means failing to do something, which does not fit a treasured memory.", "2": "A bare verb cannot follow ''forget''.", "3": "''To seeing'' is not correct here."}'),
  ('ENG-0368', 'English', 'Infinitives and gerunds', 'Change of meaning: gerund or infinitive', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.5', 'Choose the option that correctly fills the blank:
He stopped ______ a glass of water because he was tired after the run.', '["drinking", "drink", "to drink", "drank"]', 2, '''Stop + to-infinitive'' means stopping one activity in order to do another (to drink water).', '{"0": "''Stopped drinking'' would mean he gave up drinking.", "1": "A bare verb cannot follow ''stopped''.", "3": "A past form cannot follow ''stopped''."}'),
  ('ENG-0369', 'English', 'Infinitives and gerunds', 'Identifying gerunds', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.6', 'In "Her hobby is painting landscapes", the word "painting" is used as:', '["a present participle (an adjective)", "the main verb", "an infinitive", "a gerund (a noun)"]', 3, '''Painting landscapes'' names the hobby and completes ''is'', so it works as a noun: a gerund.', '{"0": "It does not describe a noun.", "1": "The main verb is ''is''.", "2": "An infinitive would be ''to paint''."}'),
  ('ENG-0370', 'English', 'Infinitives and gerunds', 'Functions of the infinitive', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.5', 'In "She wants to become a doctor", the infinitive phrase "to become a doctor" works as:', '["the object of ''wants''", "the subject", "an adverb of purpose", "an adjective"]', 0, 'It answers ''wants what?'', so it is the object of the verb.', '{"1": "The subject is ''She''.", "2": "It does not explain why she does something.", "3": "It does not describe a noun."}'),
  ('ENG-0371', 'English', 'Adverbs', 'Position of adverbs', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.7', 'Which sentence places the adverb correctly?', '["I have finished already my assignment.", "I have already finished my assignment.", "Already I have my assignment finished.", "I already have my finished assignment."]', 1, '''Already'' normally goes between the auxiliary ''have'' and the past participle.', '{"0": "An adverb should not separate a verb from its object.", "2": "This word order is not natural English.", "3": "This changes the meaning; ''finished'' now describes the assignment."}'),
  ('ENG-0372', 'English', 'Adverbs', 'Position of adverbs', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.7', 'Which sentence places the adverb correctly?', '["He speaks fluently English.", "He fluently English speaks.", "He speaks English fluently.", "Fluently he English speaks."]', 2, 'An adverb of manner usually comes after the object, not between the verb and its object.', '{"0": "The adverb wrongly separates the verb from its object.", "1": "This word order is not English.", "3": "This word order is not English."}'),
  ('ENG-0373', 'English', 'Adverbs', 'Position changes meaning', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.7', 'Which sentence means that Sara did nothing else except read the report (she did not discuss or sign it)?', '["Only Sara read the report.", "Sara read only the report.", "Sara read the report only yesterday.", "Sara only read the report."]', 3, '''Only'' placed before the verb limits the action: reading was all she did.', '{"0": "This means nobody except Sara read it.", "1": "This means she read nothing except the report.", "2": "This limits the time, not the action."}'),
  ('ENG-0374', 'English', 'Adverbs', 'Adverbs of degree', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.7', 'Choose the option that correctly fills the blank:
The patient is ______ better today.', '["much", "many", "very", "more"]', 0, '''Much'' is the adverb of degree used to strengthen a comparative like ''better''.', '{"1": "''Many'' is used with plural nouns.", "2": "''Very'' cannot modify a comparative (''very better'' is wrong).", "3": "''More better'' is a double comparative."}'),
  ('ENG-0375', 'English', 'Adverbs', 'Kinds of adverbs', 'easy', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.7', 'Choose the option that correctly fills the blank:
She ______ goes to the gym, perhaps once a year.', '["usually", "rarely", "always", "often"]', 1, 'Once a year is very infrequent, so the adverb of frequency is ''rarely''.', '{"0": "''Usually'' means most of the time.", "2": "''Always'' means every time.", "3": "''Often'' means many times."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10, s.column11,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('ENG-0376', 'English', 'Adverbs', 'Adjective or adverb', 'easy', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.7', 'Choose the option that correctly fills the blank:
He answered the question ______.', '["correct", "corrected", "correctly", "correctness"]', 2, 'The word modifies the verb ''answered'', so the adverb ''correctly'' is needed.', '{"0": "''Correct'' is an adjective.", "1": "''Corrected'' is a verb form.", "3": "''Correctness'' is a noun."}'),
  ('ENG-0377', 'English', 'Adverbs', 'Adjective or adverb', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.7', 'Choose the option that correctly fills the blank:
The flowers smell ______.', '["sweetly", "sweetness", "sweeten", "sweet"]', 3, '''Smell'' here is a linking verb describing the flowers, so it takes an adjective, not an adverb.', '{"0": "An adverb would describe how the flowers perform the act of smelling.", "1": "A noun cannot complete the linking verb here.", "2": "''Sweeten'' is a verb."}'),
  ('ENG-0378', 'English', 'Adverbs', 'Order of adverbs', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.7', 'Which sentence has the adverbs in the usual order?', '["She worked hard in the lab yesterday.", "She worked yesterday in the lab hard.", "She worked in the lab hard yesterday.", "She worked yesterday hard in the lab."]', 0, 'The usual order after the verb is manner, then place, then time: hard, in the lab, yesterday.', '{"1": "Time and manner are in the wrong places.", "2": "Manner should come before place.", "3": "Time should come last."}'),
  ('ENG-0379', 'English', 'Adverbs', 'Kinds of adverbs', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.7', 'In "Why did you leave early?", the word "Why" is:', '["a relative pronoun", "an interrogative adverb", "an adverb of manner", "a conjunction"]', 1, '''Why'' asks a question about reason and modifies the verb, so it is an interrogative adverb.', '{"0": "It does not refer back to a noun.", "2": "It asks for a reason, not the way something was done.", "3": "It does not join two clauses here."}'),
  ('ENG-0380', 'English', 'Prepositions', 'Fixed prepositions', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.8', 'Choose the option that correctly fills the blank:
She has been absent ______ college for three days.', '["of", "at", "from", "in"]', 2, 'The fixed expression is ''absent from''.', '{"0": "''Absent of'' is not standard.", "1": "''Absent at'' is not standard.", "3": "''Absent in'' is not standard."}'),
  ('ENG-0381', 'English', 'Prepositions', 'Fixed prepositions', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.8', 'Choose the option that correctly fills the blank:
This medicine is not suitable ______ children under five.', '["to", "with", "at", "for"]', 3, 'The fixed expression is ''suitable for''.', '{"0": "''Suitable to'' is not used for people here.", "1": "''Suitable with'' is wrong.", "2": "''Suitable at'' is wrong."}'),
  ('ENG-0382', 'English', 'Prepositions', 'Fixed prepositions', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.8', 'Choose the option that correctly fills the blank:
The new medicine is superior ______ the old one.', '["to", "than", "from", "over"]', 0, '''Superior'' is followed by ''to'', not ''than''.', '{"1": "''Superior than'' is a common error.", "2": "''Superior from'' is wrong.", "3": "''Superior over'' is not standard."}'),
  ('ENG-0383', 'English', 'Prepositions', 'Prepositions of position', 'easy', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.8', 'Choose the option that correctly fills the blank:
Divide the sweets ______ the two children.', '["among", "between", "in", "with"]', 1, '''Between'' is used for two people or things.', '{"0": "''Among'' is used for more than two.", "2": "''In'' does not express sharing.", "3": "''With'' does not express sharing between people."}'),
  ('ENG-0384', 'English', 'Prepositions', 'Prepositions of position', 'easy', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.8', 'Choose the option that correctly fills the blank:
The money was distributed ______ the five winners.', '["between", "with", "among", "on"]', 2, '''Among'' is used for more than two people.', '{"0": "''Between'' is for two.", "1": "''With'' does not express distribution.", "3": "''On'' does not fit."}'),
  ('ENG-0385', 'English', 'Prepositions', 'Prepositions of movement', 'easy', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.8', 'Choose the option that correctly fills the blank:
The ball rolled ______ the bed and could not be reached.', '["over", "on", "among", "under"]', 3, '''Under'' shows a position below something; a ball under the bed is hard to reach.', '{"0": "''Over'' means above or across.", "1": "''On'' means resting on top.", "2": "''Among'' is used for being in a group of things."}'),
  ('ENG-0386', 'English', 'Prepositions', 'Since and for', 'easy', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.8', 'Choose the option that correctly fills the blank:
I have been waiting ______ two o''clock.', '["since", "for", "from", "at"]', 0, '''Since'' is used with a point in time.', '{"1": "''For'' is used with a length of time, like ''two hours''.", "2": "''From'' needs ''to'' or ''until'' to complete it.", "3": "''At'' does not go with the present perfect continuous here."}'),
  ('ENG-0387', 'English', 'Prepositions', 'Fixed prepositions', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.8', 'Choose the option that correctly fills the blank:
She congratulated me ______ my success.', '["for", "on", "at", "about"]', 1, 'The fixed expression is ''congratulate someone on something''.', '{"0": "''Congratulate for'' is a common error.", "2": "''Congratulate at'' is wrong.", "3": "''Congratulate about'' is wrong."}'),
  ('ENG-0388', 'English', 'Prepositions', 'Prepositions of time', 'easy', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.8', 'Choose the option that correctly fills the blank:
The clinic is closed ______ Sundays.', '["in", "at", "on", "by"]', 2, '''On'' is used with days of the week.', '{"0": "''In'' is used with months, years and parts of the day.", "1": "''At'' is used with clock times.", "3": "''By'' means ''not later than'', which does not fit."}'),
  ('ENG-0389', 'English', 'Prepositions', 'Fixed prepositions', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.8', 'Choose the option that correctly fills the blank:
He was accused ______ cheating in the exam.', '["for", "with", "on", "of"]', 3, 'The fixed expression is ''accused of''.', '{"0": "''Accused for'' is wrong.", "1": "''Accused with'' is wrong.", "2": "''Accused on'' is wrong."}'),
  ('ENG-0390', 'English', 'Transitional devices', 'Contrast', 'easy', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.9', 'Choose the option that correctly fills the blank:
The medicine is effective; ______, it has several side effects.', '["however", "therefore", "for example", "similarly"]', 0, 'The second clause contrasts with the first, so a contrast transition is needed.', '{"1": "''Therefore'' shows a result, but side effects do not result from effectiveness.", "2": "''For example'' introduces an example of the first idea.", "3": "''Similarly'' shows likeness, not contrast."}'),
  ('ENG-0391', 'English', 'Transitional devices', 'Cause and result', 'easy', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.9', 'Choose the option that correctly fills the blank:
He did not prepare for the viva. ______, he could not answer the simplest questions.', '["In contrast", "As a result", "Moreover", "For instance"]', 1, 'Not preparing caused him to fail the questions, so a result transition fits.', '{"0": "There is no contrast between the two ideas.", "2": "''Moreover'' adds a new point instead of showing a consequence.", "3": "The second sentence is not an example."}'),
  ('ENG-0392', 'English', 'Transitional devices', 'Example', 'easy', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.9', 'Choose the option that correctly fills the blank:
Some vitamins dissolve in fat, ______ vitamins A, D, E and K.', '["however", "therefore", "such as", "although"]', 2, 'The names that follow are examples, so ''such as'' is needed.', '{"0": "''However'' shows contrast.", "1": "''Therefore'' shows result.", "3": "''Although'' introduces a contrasting clause."}'),
  ('ENG-0393', 'English', 'Transitional devices', 'Contrast', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.9', 'Choose the option that correctly fills the blank:
______ the medicine was expensive, his family bought it.', '["Because", "Therefore", "In addition", "Even though"]', 3, 'Buying the medicine despite its cost is a contrast, introduced by ''even though''.', '{"0": "Expense is not a reason for buying.", "1": "''Therefore'' cannot introduce a subordinate clause here.", "2": "''In addition'' adds a point; it cannot introduce this clause."}'),
  ('ENG-0394', 'English', 'Transitional devices', 'Cause and result', 'easy', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.9', 'Choose the option that correctly fills the blank:
The lab was closed for repairs; ______, the practical was moved to Friday.', '["therefore", "nevertheless", "for instance", "in contrast"]', 0, 'Moving the practical is a result of the lab being closed.', '{"1": "''Nevertheless'' shows contrast, not result.", "2": "This is not an example.", "3": "There is no contrast."}'),
  ('ENG-0395', 'English', 'Transitional devices', 'Addition', 'easy', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.9', 'Choose the option that correctly fills the blank:
Smoking damages the lungs. ______, it raises the risk of heart disease.', '["Nevertheless", "Furthermore", "Instead", "Otherwise"]', 1, 'The second sentence adds another harmful effect, so an addition transition fits.', '{"0": "There is no contrast.", "2": "''Instead'' introduces a replacement.", "3": "''Otherwise'' introduces what happens if a condition is not met."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10, s.column11,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('ENG-0396', 'English', 'Transitional devices', 'Purpose', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.9', 'Choose the option that correctly fills the blank:
Keep the vaccine refrigerated ______ it does not lose its strength.', '["even though", "unless", "so that", "whereas"]', 2, 'Refrigeration has the purpose of keeping the vaccine strong, so ''so that'' fits.', '{"0": "There is no contrast.", "1": "''Unless'' gives the opposite logic.", "3": "''Whereas'' compares two contrasting facts."}'),
  ('ENG-0397', 'English', 'Transitional devices', 'Contrast', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.9', 'Choose the option that correctly fills the blank:
Ali prefers biology, ______ his sister prefers physics.', '["because", "so", "therefore", "whereas"]', 3, 'The sentence contrasts two people''s preferences, so ''whereas'' fits.', '{"0": "Her preference is not the reason for his.", "1": "One preference does not result from the other.", "2": "''Therefore'' shows result."}'),
  ('ENG-0398', 'English', 'Transitional devices', 'Sequence', 'easy', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.9', 'Choose the option that correctly fills the blank:
Read each question carefully. ______, check your answers before handing in the paper.', '["Finally", "However", "Consequently", "For example"]', 0, 'The second step comes last in the sequence, so ''Finally'' fits.', '{"1": "There is no contrast.", "2": "Checking is not a result of reading.", "3": "Checking is not an example of reading."}'),
  ('ENG-0399', 'English', 'Transitional devices', 'Addition', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.9', 'Choose the option that correctly fills the blank:
She was not only intelligent ______ hardworking.', '["and also not", "but also", "or", "nor"]', 1, '''Not only'' pairs with ''but also''.', '{"0": "''And also not'' would contradict the meaning.", "2": "''Or'' does not pair with ''not only''.", "3": "''Nor'' pairs with ''neither''."}'),
  ('ENG-0400', 'English', 'Punctuation', 'Apostrophe', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.10', 'Which sentence is punctuated correctly?', '["The student''s results were announced on Friday, by the board.", "The students results'' were announced on Friday.", "The students'' results were announced on Friday.", "The students''s results were announced on Friday."]', 2, 'For a plural noun ending in -s, the possessive apostrophe goes after the s: students''.', '{"0": "The comma before ''by the board'' is unnecessary, and the singular ''student''s'' does not fit ''results'' of many students.", "1": "The apostrophe belongs on the owner (students), not on ''results''.", "3": "A plural ending in -s takes only an apostrophe, not ''s."}'),
  ('ENG-0401', 'English', 'Punctuation', 'Apostrophe', 'easy', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.10', 'Which sentence is punctuated correctly?', '["Whose coming to the seminar?", "Who''s coming to the seminar.", "Whos coming to the seminar?", "Who''s coming to the seminar?"]', 3, '''Who''s'' is short for ''who is'', and a direct question ends with a question mark.', '{"0": "''Whose'' shows possession; here we need ''who is''.", "1": "A direct question needs a question mark, not a full stop.", "2": "The contraction needs an apostrophe."}'),
  ('ENG-0402', 'English', 'Punctuation', 'Comma', 'easy', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.10', 'Which sentence is punctuated correctly?', '["He bought eggs, milk, bread and butter.", "He bought eggs milk bread and butter.", "He bought, eggs, milk, bread and butter.", "He bought eggs, milk, bread, and, butter."]', 0, 'Items in a list are separated by commas; no comma is needed between the verb and its object.', '{"1": "The list items need commas between them.", "2": "There should be no comma between ''bought'' and its object.", "3": "There should be no comma after ''and''."}'),
  ('ENG-0403', 'English', 'Punctuation', 'Comma', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.10', 'Which sentence is punctuated correctly?', '["Dr. Imran our family doctor, has retired.", "Dr. Imran, our family doctor, has retired.", "Dr. Imran, our family doctor has retired.", "Dr. Imran our family doctor has retired."]', 1, 'A phrase that renames a noun (an appositive) in the middle of a sentence is set off with a comma on both sides.', '{"0": "The opening comma is missing.", "2": "The closing comma is missing.", "3": "Both commas around the appositive are missing."}'),
  ('ENG-0404', 'English', 'Punctuation', 'Colon', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.10', 'Which sentence is punctuated correctly?', '["The patient had three symptoms; fever, cough and fatigue.", "The patient had: three symptoms fever, cough and fatigue.", "The patient had three symptoms: fever, cough and fatigue.", "The patient had three symptoms, fever; cough; and fatigue."]', 2, 'A colon introduces a list after a complete clause.', '{"0": "A semicolon does not introduce a list.", "1": "The colon must come after the complete clause, not after ''had''.", "3": "Semicolons are not used between simple list items."}'),
  ('ENG-0405', 'English', 'Punctuation', 'Semicolon', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.10', 'Which sentence is punctuated correctly?', '["The surgery was successful, the patient was discharged a week later.", "The surgery was successful; and the patient was discharged a week later.", "The surgery; was successful the patient was discharged a week later.", "The surgery was successful; the patient was discharged a week later."]', 3, 'A semicolon can join two closely related complete sentences without a conjunction.', '{"0": "Joining two complete sentences with only a comma is a comma splice.", "1": "A semicolon is not followed by ''and'' in this way.", "2": "The semicolon is in the wrong place."}'),
  ('ENG-0406', 'English', 'Punctuation', 'Quotation marks', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.10', 'Which sentence is punctuated correctly?', '["\"Where are you going?\" asked the nurse.", "\"Where are you going,\" asked the nurse.", "\"Where are you going\"? asked the nurse.", "\"Where are you going?,\" asked the nurse."]', 0, 'A question inside quotation marks keeps its question mark inside the closing quotation mark, with no extra comma.', '{"1": "A question needs a question mark, not a comma.", "2": "The question mark belongs inside the quotation marks.", "3": "No comma follows a question mark."}'),
  ('ENG-0407', 'English', 'Punctuation', 'Hyphen', 'easy', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.10', 'Which sentence is punctuated correctly?', '["My brother in-law is a dentist.", "My brother-in-law is a dentist.", "My brother-in law is a dentist.", "My brother in law, is a dentist."]', 1, 'Compound nouns such as ''brother-in-law'' are hyphenated throughout.', '{"0": "Both hyphens are needed.", "2": "Both hyphens are needed.", "3": "Hyphens are needed, and no comma goes before the verb."}'),
  ('ENG-0408', 'English', 'Punctuation', 'Capital letters', 'easy', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.10', 'Which sentence is punctuated correctly?', '["we will meet on monday, 3 march, in islamabad.", "We will meet on monday, 3 March, in Islamabad.", "We will meet on Monday, 3 March, in Islamabad.", "We will meet on Monday, 3 march, in islamabad."]', 2, 'Sentences begin with a capital, and days, months and place names are proper nouns that take capitals.', '{"0": "The first word and all proper nouns need capitals.", "1": "''Monday'' needs a capital.", "3": "''March'' and ''Islamabad'' need capitals."}'),
  ('ENG-0409', 'English', 'Punctuation', 'Comma', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.10', 'Which sentence is punctuated correctly?', '["Although it was late the doctor, agreed to see the patient.", "Although, it was late the doctor agreed to see the patient.", "Although it was late; the doctor agreed to see the patient.", "Although it was late, the doctor agreed to see the patient."]', 3, 'When a dependent clause comes first, a comma separates it from the main clause.', '{"0": "The comma is misplaced, splitting the subject from its verb.", "1": "There should be no comma after ''although''.", "2": "A semicolon cannot join a dependent clause to a main clause."}'),
  ('ENG-0410', 'English', 'Phrases, clauses and inversion', 'Phrases and clauses', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.11', 'In "What the doctor said surprised everyone.", the words "What the doctor said" form:', '["a noun clause", "an adjective clause", "an adverb clause", "a prepositional phrase"]', 0, 'The clause has a subject and verb (''the doctor said'') and is the subject of ''surprised'', so it works as a noun.', '{"1": "It does not describe a noun.", "2": "It does not tell how, when, where or why.", "3": "It has a subject and verb, so it is a clause, not a phrase."}'),
  ('ENG-0411', 'English', 'Phrases, clauses and inversion', 'Phrases and clauses', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.11', 'In "The village where my grandparents live has no hospital.", the words "where my grandparents live" form:', '["a noun clause", "an adjective clause", "an adverb clause", "a prepositional phrase"]', 1, 'The clause describes the noun ''village'' (which village?), so it works as an adjective (relative) clause.', '{"0": "It is not the subject or object of a verb.", "2": "It describes a noun, not a verb.", "3": "It has a subject and verb (''grandparents live''), so it is a clause."}'),
  ('ENG-0412', 'English', 'Phrases, clauses and inversion', 'Phrases and clauses', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.11', 'In "Call me when you reach the hostel.", the words "when you reach the hostel" form:', '["a noun clause", "an adjective clause", "an adverb clause", "a noun phrase"]', 2, 'The clause tells when to call, so it modifies the verb as an adverb clause of time.', '{"0": "It does not act as a subject or object.", "1": "It does not describe a noun.", "3": "It has a subject and verb, so it is a clause."}'),
  ('ENG-0413', 'English', 'Phrases, clauses and inversion', 'Phrases and clauses', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.11', 'In "Walking along the beach, she found a shell.", the words "Walking along the beach" form:', '["a noun clause", "an adverb clause", "an independent clause", "a participial phrase"]', 3, 'The group has a participle (''walking'') but no subject and finite verb, and it describes ''she''.', '{"0": "It has no subject and finite verb, so it is not a clause.", "1": "It has no subject and finite verb, so it is not a clause.", "2": "It cannot stand alone as a sentence."}'),
  ('ENG-0414', 'English', 'Phrases, clauses and inversion', 'Kinds of sentences', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.11', 'Which of these is a COMPLEX sentence?', '["She stayed at home because she was ill.", "She was ill, so she stayed at home.", "She was ill and stayed at home.", "She was ill. She stayed at home."]', 0, 'A complex sentence has one main clause and at least one dependent clause; ''because she was ill'' is dependent.', '{"1": "Two main clauses joined by ''so'' make a compound sentence.", "2": "This is a simple sentence with a compound verb.", "3": "These are two simple sentences."}'),
  ('ENG-0415', 'English', 'Phrases, clauses and inversion', 'Sentence fragments', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.11', 'Which of these is a sentence FRAGMENT?', '["The nurse ran down the corridor.", "Running down the corridor with a tray of medicines.", "Running is good for the heart.", "She was running down the corridor with a tray of medicines."]', 1, 'This group of words has no subject and no finite verb, so it is not a complete sentence.', '{"0": "This has a subject and a finite verb.", "2": "''Running'' is the subject and ''is'' the verb, so it is complete.", "3": "This has a subject and a finite verb (''was running'')."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10, s.column11,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('ENG-0416', 'English', 'Phrases, clauses and inversion', 'Misplaced modifiers', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.11', 'Which sentence is written correctly?', '["Having finished the paper early, the answers were checked by Bilal.", "Having finished the paper early, the invigilator collected Bilal''s script.", "Having finished the paper early, Bilal checked his answers.", "Bilal''s answers, having finished the paper early, were checked."]', 2, 'The opening phrase must describe the subject that follows; Bilal is the one who finished early.', '{"0": "This suggests the answers finished the paper.", "1": "This suggests the invigilator finished the paper.", "3": "This suggests the answers finished the paper."}'),
  ('ENG-0417', 'English', 'Phrases, clauses and inversion', 'Inversion', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.12', 'Choose the option that correctly fills the blank:
Seldom ______ so many patients in one day.', '["the clinic has treated", "the clinic treated", "treated the clinic has", "has the clinic treated"]', 3, 'When ''seldom'' begins a sentence, the auxiliary ''has'' comes before the subject.', '{"0": "Normal word order is wrong after an opening ''seldom''.", "1": "There is no auxiliary to invert.", "2": "The word order is jumbled."}'),
  ('ENG-0418', 'English', 'Phrases, clauses and inversion', 'Inversion', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.12', 'Choose the option that correctly fills the blank:
No sooner ______ the hall than the fire alarm rang.', '["had we entered", "we had entered", "we entered", "did we entered"]', 0, '''No sooner'' at the start takes inversion with the past perfect and is followed by ''than''.', '{"1": "Normal word order is wrong after an opening ''no sooner''.", "2": "Inversion with an auxiliary is needed.", "3": "''Did'' must be followed by the base form, and this pattern uses ''had''."}'),
  ('ENG-0419', 'English', 'Phrases, clauses and inversion', 'Inversion', 'easy', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.12', 'Choose the option that correctly fills the blank:
Rarely ______ such a skilled surgeon.', '["I have met", "have I met", "I met", "met I"]', 1, 'When ''rarely'' begins a sentence, the auxiliary comes before the subject.', '{"0": "Normal word order is wrong after an opening ''rarely''.", "2": "There is no auxiliary to invert.", "3": "The main verb cannot be inverted this way."}'),
  ('ENG-0420', 'English', 'Phrases, clauses and inversion', 'Inversion', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.12', 'Choose the option that correctly fills the blank:
______ I known about the strike, I would have left earlier.', '["If", "Have", "Had", "Did"]', 2, '''Had I known'' is an inverted form of ''If I had known'' in a third conditional.', '{"0": "''If I known'' is ungrammatical; ''if'' would need ''had''.", "1": "''Have I known'' does not fit the past conditional.", "3": "''Did I known'' is ungrammatical."}'),
  ('ENG-0421', 'English', 'Phrases, clauses and inversion', 'Inversion', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.12', 'Choose the option that correctly fills the blank:
Under no circumstances ______ leave the patient alone.', '["you should", "you will", "should not you", "should you"]', 3, 'An opening negative phrase like ''under no circumstances'' requires inversion: ''should you''.', '{"0": "Normal word order is wrong after an opening negative phrase.", "1": "Normal word order is wrong, and the modal must come first.", "2": "The phrase is already negative, so ''not'' makes a double negative."}'),
  ('ENG-0422', 'English', 'Active and passive voice', 'Active to passive', 'easy', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.13', 'Choose the correct passive form of:
"The teacher is checking the papers."', '["The papers are being checked by the teacher.", "The papers are checked by the teacher.", "The papers were being checked by the teacher.", "The papers have been checked by the teacher."]', 0, 'Present continuous active becomes am/is/are + being + past participle.', '{"1": "This is simple present passive.", "2": "This is past continuous passive.", "3": "This is present perfect passive."}'),
  ('ENG-0423', 'English', 'Active and passive voice', 'Active to passive', 'easy', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.13', 'Choose the correct passive form of:
"They will announce the results tomorrow."', '["The results would be announced tomorrow.", "The results will be announced tomorrow.", "The results will announce tomorrow.", "The results are announced tomorrow."]', 1, 'Simple future active becomes will + be + past participle; ''by them'' can be left out.', '{"0": "''Would'' changes the tense.", "2": "This is still active in form and changes the meaning.", "3": "This is simple present passive."}'),
  ('ENG-0424', 'English', 'Active and passive voice', 'Modals in the passive', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.13', 'Choose the correct passive form of:
"You can solve this problem easily."', '["This problem could be solved easily.", "This problem can solve easily.", "This problem can be solved easily.", "This problem can be solve easily."]', 2, 'A modal in the active becomes modal + be + past participle in the passive.', '{"0": "''Could'' changes the modal.", "1": "This is not passive; it lacks ''be'' + past participle.", "3": "The passive needs the past participle ''solved''."}'),
  ('ENG-0425', 'English', 'Active and passive voice', 'Imperatives in the passive', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.13', 'Choose the correct passive form of:
"Do not touch the wires."', '["The wires are not touched.", "The wires should not touch.", "Let not touch the wires.", "Let the wires not be touched."]', 3, 'A negative command becomes ''Let ... not be + past participle'' in the passive.', '{"0": "This is a statement, not a command.", "1": "This is active in form and changes the meaning.", "2": "This is ungrammatical."}'),
  ('ENG-0426', 'English', 'Active and passive voice', 'Questions in the passive', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.13', 'Choose the correct passive form of:
"Has anyone seen my stethoscope?"', '["Has my stethoscope been seen by anyone?", "Was my stethoscope seen by anyone?", "Is my stethoscope seen by anyone?", "Had my stethoscope been seen by anyone?"]', 0, 'A present perfect question becomes has/have + subject + been + past participle.', '{"1": "This is simple past passive.", "2": "This is simple present passive.", "3": "This is past perfect passive."}'),
  ('ENG-0427', 'English', 'Active and passive voice', 'Active to passive', 'easy', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.13', 'Choose the correct passive form of:
"The flood destroyed many houses."', '["Many houses are destroyed by the flood.", "Many houses were destroyed by the flood.", "Many houses had been destroyed by the flood.", "Many houses was destroyed by the flood."]', 1, 'Simple past active becomes was/were + past participle; ''houses'' is plural, so ''were''.', '{"0": "This is simple present passive.", "2": "This is past perfect passive.", "3": "''Houses'' is plural, so ''were'' is needed."}'),
  ('ENG-0428', 'English', 'Active and passive voice', 'Passive to active', 'easy', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.13', 'Choose the correct active form of:
"The letter was written by Ali."', '["Ali writes the letter.", "Ali has written the letter.", "Ali wrote the letter.", "Ali had written the letter."]', 2, 'Simple past passive (was written) becomes simple past active (wrote).', '{"0": "This is simple present.", "1": "This is present perfect.", "3": "This is past perfect."}'),
  ('ENG-0429', 'English', 'Active and passive voice', 'Passive to active', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.13', 'Choose the correct active form of:
"The thief is being chased by the police."', '["The police chased the thief.", "The police were chasing the thief.", "The police have chased the thief.", "The police are chasing the thief."]', 3, 'Present continuous passive (is being chased) becomes present continuous active (are chasing).', '{"0": "This is simple past.", "1": "This is past continuous.", "2": "This is present perfect."}'),
  ('ENG-0430', 'English', 'Active and passive voice', 'Passive to active', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.13', 'Choose the correct active form of:
"The patients will have been examined by the doctor by noon."', '["The doctor will have examined the patients by noon.", "The doctor will examine the patients by noon.", "The doctor would have examined the patients by noon.", "The doctor had examined the patients by noon."]', 0, 'Future perfect passive (will have been examined) becomes future perfect active (will have examined).', '{"1": "This is simple future.", "2": "''Would have'' changes the meaning to a conditional.", "3": "This is past perfect."}'),
  ('ENG-0431', 'English', 'Active and passive voice', 'Recognising voice', 'easy', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.13', 'Which sentence is in the ACTIVE voice?', '["The injection was given by the nurse.", "The nurse gave the injection.", "The injection has been given.", "The injection is being given."]', 1, 'In the active voice the subject (the nurse) performs the action.', '{"0": "The subject receives the action, so it is passive.", "2": "This is present perfect passive.", "3": "This is present continuous passive."}'),
  ('ENG-0432', 'English', 'Direct and indirect speech', 'Questions', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.14', 'Choose the correct indirect form of:
He said to me, "Did you see the match?"', '["He asked me whether I saw the match.", "He asked me did I see the match.", "He asked me whether I had seen the match.", "He told me that I had seen the match."]', 2, 'A yes/no question is reported with ''asked + if/whether'', statement word order, and simple past shifting to past perfect.', '{"0": "The tense should shift back from simple past to past perfect.", "1": "Reported questions do not keep question word order.", "3": "''Told ... that'' turns the question into a statement."}'),
  ('ENG-0433', 'English', 'Direct and indirect speech', 'Questions', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.14', 'Choose the correct indirect form of:
She said, "Why are you late?"', '["She asked why was I late.", "She asked why I am late.", "She said why I was late.", "She asked why I was late."]', 3, 'A wh-question keeps the question word, uses statement word order, and ''are'' shifts to ''was''.', '{"0": "Reported questions do not keep question word order.", "1": "The tense should shift back.", "2": "A question is reported with ''asked'', not ''said''."}'),
  ('ENG-0434', 'English', 'Direct and indirect speech', 'Commands and requests', 'easy', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.14', 'Choose the correct indirect form of:
The teacher said to the students, "Do not make a noise."', '["The teacher told the students not to make a noise.", "The teacher told the students to not making a noise.", "The teacher said the students do not make a noise.", "The teacher told the students that do not make a noise."]', 0, 'A negative command becomes ''told/ordered + object + not to + verb''.', '{"1": "''To not making'' is ungrammatical.", "2": "A command is not reported as a statement with ''said''.", "3": "''That'' cannot introduce an imperative."}'),
  ('ENG-0435', 'English', 'Direct and indirect speech', 'Exclamations', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.14', 'Choose the correct indirect form of:
He said, "Alas! I have failed."', '["He exclaimed with joy that he had failed.", "He exclaimed with sorrow that he had failed.", "He said alas that he has failed.", "He exclaimed with sorrow that I had failed."]', 1, '''Alas'' shows sorrow; ''have failed'' shifts back to ''had failed'' and ''I'' becomes ''he''.', '{"0": "''Alas'' expresses sorrow, not joy.", "2": "The interjection is dropped and the tense must shift back.", "3": "The pronoun should change to ''he''."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10, s.column11,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('ENG-0436', 'English', 'Direct and indirect speech', 'Statements', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.14', 'Choose the correct indirect form of:
She said, "I am going to the market now."', '["She said that she is going to the market now.", "She said that she was going to the market now.", "She said that she was going to the market then.", "She said that I was going to the market then."]', 2, '''Am going'' shifts to ''was going'' and ''now'' becomes ''then''.', '{"0": "The tense must shift back and ''now'' must change.", "1": "''Now'' should change to ''then''.", "3": "The pronoun should be ''she''."}'),
  ('ENG-0437', 'English', 'Direct and indirect speech', 'Statements', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.14', 'Choose the correct indirect form of:
He said, "I will meet you here tomorrow."', '["He said that he will meet me here tomorrow.", "He said that he would meet me here tomorrow.", "He said that he would meet you there the next day.", "He said that he would meet me there the next day."]', 3, '''Will'' becomes ''would'', ''here'' becomes ''there'', ''tomorrow'' becomes ''the next day'', and ''you'' (the listener) becomes ''me''.', '{"0": "Nothing has been shifted.", "1": "''Here'' and ''tomorrow'' should change.", "2": "From the listener''s report, ''you'' becomes ''me''."}'),
  ('ENG-0438', 'English', 'Direct and indirect speech', 'Commands and requests', 'easy', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.14', 'Choose the correct indirect form of:
She said to me, "Please lend me your notes."', '["She requested me to lend her my notes.", "She ordered me to lend her my notes.", "She requested me to lend me your notes.", "She said me to lend her my notes."]', 0, '''Please'' shows a request, so the reporting verb is ''requested''; pronouns change to ''her'' and ''my''.', '{"1": "''Please'' shows a polite request, not an order.", "2": "The pronouns have not been changed.", "3": "''Said me to'' is ungrammatical."}'),
  ('ENG-0439', 'English', 'Direct and indirect speech', 'Statements', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.14', 'Choose the correct indirect form of:
The doctor said, "You must get some rest."', '["The doctor said that I must got some rest.", "The doctor said that I had to get some rest.", "The doctor said that you have to get some rest.", "The doctor said that I had got some rest."]', 1, 'In reported speech, ''must'' (obligation) usually becomes ''had to'' after a past reporting verb, and ''you'' becomes ''I'' when the listener reports it.', '{"0": "''Must'' is followed by the base form, never ''got''.", "2": "Neither the tense nor the pronoun has been shifted.", "3": "''Had got'' changes the meaning from an obligation to something already done."}'),
  ('ENG-0440', 'English', 'Direct and indirect speech', 'Indirect to direct', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 2.14', 'Choose the correct direct form of:
He asked me where I was going.', '["He said to me, \"Where were you going?\"", "He said to me, \"Where am I going?\"", "He said to me, \"Where are you going?\"", "He said to me, \"Where you are going?\""]', 2, 'Going back to direct speech, ''was going'' becomes ''are going'', ''I'' becomes ''you'', and question word order returns.', '{"0": "The tense should return to the present.", "1": "The pronoun should be ''you''.", "3": "A direct question needs inverted word order."}'),
  ('ENG-0441', 'English', 'Subject-verb agreement', 'Words between subject and verb', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 3.3', 'Choose the option that correctly fills the blank:
The list of items ______ on the desk.', '["are", "were", "have been", "is"]', 3, 'The subject is ''the list'' (singular); ''of items'' does not change it.', '{"0": "''Items'' is not the subject.", "1": "''Items'' is not the subject.", "2": "''Items'' is not the subject; ''have'' would need a plural subject."}'),
  ('ENG-0442', 'English', 'Subject-verb agreement', 'Indefinite pronouns', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 3.3', 'Choose the option that correctly fills the blank:
Neither of the answers ______ correct.', '["is", "are", "were", "have been"]', 0, '''Neither'' as a subject is singular.', '{"1": "''Neither'' is singular in formal English.", "2": "The tense and number are wrong.", "3": "''Neither'' is singular."}'),
  ('ENG-0443', 'English', 'Subject-verb agreement', 'Nouns ending in -s', 'easy', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 3.3', 'Choose the option that correctly fills the blank:
Measles ______ a highly infectious disease.', '["are", "is", "were", "have been"]', 1, 'Names of diseases ending in -s, like measles, take a singular verb.', '{"0": "''Measles'' is singular in meaning.", "2": "The tense and number are wrong.", "3": "''Measles'' is singular."}'),
  ('ENG-0444', 'English', 'Subject-verb agreement', 'Amounts', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 3.3', 'Choose the option that correctly fills the blank:
Five hundred rupees ______ too much for this book.', '["are", "were", "is", "have"]', 2, 'An amount of money treated as one sum takes a singular verb.', '{"0": "The amount is treated as one sum.", "1": "The tense and number are wrong.", "3": "''Have'' does not fit the meaning."}'),
  ('ENG-0445', 'English', 'Subject-verb agreement', 'Compound subjects', 'easy', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 3.3', 'Choose the option that correctly fills the blank:
The doctor and the nurse ______ on duty tonight.', '["is", "was", "has been", "are"]', 3, 'Two different people joined by ''and'' make a plural subject.', '{"0": "Two people make a plural subject.", "1": "Two people make a plural subject.", "2": "Two people make a plural subject."}'),
  ('ENG-0446', 'English', 'Subject-verb agreement', 'Compound subjects', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 3.3', 'Choose the option that correctly fills the blank:
The doctor and surgeon ______ arrived.', '["has", "have", "are", "were"]', 0, 'With only one ''the'', ''the doctor and surgeon'' refers to one person who is both, so the verb is singular.', '{"1": "One article means one person.", "2": "''Are arrived'' is ungrammatical and plural.", "3": "''Were arrived'' is ungrammatical and plural."}'),
  ('ENG-0447', 'English', 'Subject-verb agreement', 'Neither...nor and either...or', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 3.3', 'Choose the option that correctly fills the blank:
Either Ali or his sisters ______ the dishes every night.', '["washes", "wash", "is washing", "has washed"]', 1, 'With either...or, the verb agrees with the nearer subject, ''sisters'' (plural).', '{"0": "The nearer subject is plural.", "2": "The nearer subject is plural.", "3": "The nearer subject is plural."}'),
  ('ENG-0448', 'English', 'Subject-verb agreement', 'There is / there are', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 3.3', 'Choose the option that correctly fills the blank:
Here ______ the reports you asked for.', '["is", "was", "are", "has been"]', 2, 'In a sentence starting with ''here'', the subject comes after the verb; ''reports'' is plural.', '{"0": "The subject ''reports'' is plural.", "1": "The subject is plural and the tense is wrong.", "3": "The subject is plural."}'),
  ('ENG-0449', 'English', 'Subject-verb agreement', 'Compound subjects', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 3.3', 'Choose the option that correctly fills the blank:
Each boy and each girl ______ given a certificate.', '["were", "are", "have been", "was"]', 3, 'When ''each'' or ''every'' comes before subjects joined by ''and'', the verb is singular.', '{"0": "''Each ... and each'' takes a singular verb.", "1": "''Each ... and each'' takes a singular verb.", "2": "''Each ... and each'' takes a singular verb."}'),
  ('ENG-0450', 'English', 'Subject-verb agreement', 'Collective nouns', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 3.3', 'Choose the option that correctly fills the blank:
The team ______ won every match this season.', '["has", "are", "were", "having"]', 0, 'The present perfect needs ''has'' + past participle; a team acting as one unit takes the singular ''has''.', '{"1": "''Are won'' is passive in form and changes the meaning.", "2": "''Were won'' is passive and changes the meaning.", "3": "''Having'' cannot be the main verb of a sentence."}'),
  ('ENG-0451', 'English', 'Sentence correction and spelling', 'Spelling', 'easy', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 3.4', 'Which word is spelled correctly?', '["definately", "definitely", "defintely", "definitly"]', 1, 'The correct spelling is ''definitely''.', '{"0": "''definately'' is a misspelling of ''definitely''.", "2": "''defintely'' is a misspelling of ''definitely''.", "3": "''definitly'' is a misspelling of ''definitely''."}'),
  ('ENG-0452', 'English', 'Sentence correction and spelling', 'Spelling', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 3.4', 'Which word is spelled correctly?', '["neumonia", "pnuemonia", "pneumonia", "pneumonea"]', 2, 'The correct spelling is ''pneumonia''.', '{"0": "''neumonia'' is a misspelling of ''pneumonia''.", "1": "''pnuemonia'' is a misspelling of ''pneumonia''.", "3": "''pneumonea'' is a misspelling of ''pneumonia''."}'),
  ('ENG-0453', 'English', 'Sentence correction and spelling', 'Spelling', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 3.4', 'Which word is spelled correctly?', '["haemorrage", "haemorhhage", "haemorhage", "haemorrhage"]', 3, 'The correct spelling is ''haemorrhage''.', '{"0": "''haemorrage'' is a misspelling of ''haemorrhage''.", "1": "''haemorhhage'' is a misspelling of ''haemorrhage''.", "2": "''haemorhage'' is a misspelling of ''haemorrhage''."}'),
  ('ENG-0454', 'English', 'Sentence correction and spelling', 'Spelling', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 3.4', 'Which word is spelled correctly?', '["questionnaire", "questionaire", "questionnair", "questionnare"]', 0, 'The correct spelling is ''questionnaire''.', '{"1": "''questionaire'' is a misspelling of ''questionnaire''.", "2": "''questionnair'' is a misspelling of ''questionnaire''.", "3": "''questionnare'' is a misspelling of ''questionnaire''."}'),
  ('ENG-0455', 'English', 'Sentence correction and spelling', 'Spelling', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 3.4', 'Which word is spelled correctly?', '["conscientous", "conscientious", "consciencious", "concientious"]', 1, 'The correct spelling is ''conscientious''.', '{"0": "''conscientous'' is a misspelling of ''conscientious''.", "2": "''consciencious'' is a misspelling of ''conscientious''.", "3": "''concientious'' is a misspelling of ''conscientious''."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10, s.column11,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('ENG-0456', 'English', 'Sentence correction and spelling', 'Spelling', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 3.4', 'Which word is spelled correctly?', '["maintainance", "maintenence", "maintenance", "maintanance"]', 2, 'The correct spelling is ''maintenance''.', '{"0": "''maintainance'' is a misspelling of ''maintenance''.", "1": "''maintenence'' is a misspelling of ''maintenance''.", "3": "''maintanance'' is a misspelling of ''maintenance''."}'),
  ('ENG-0457', 'English', 'Sentence correction and spelling', 'Spelling', 'easy', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 3.4', 'Which word is spelled INCORRECTLY?', '["believe", "achieve", "piece", "recieve"]', 3, '''recieve'' should be spelled ''receive''.', '{"0": "''believe'' is spelled correctly.", "1": "''achieve'' is spelled correctly.", "2": "''piece'' is spelled correctly."}'),
  ('ENG-0458', 'English', 'Sentence correction and spelling', 'Choosing the correct sentence', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 3.1', 'Which sentence is correct?', '["He has been working here for ten years.", "He is working here since ten years.", "He has been working here since ten years.", "He works here from ten years."]', 0, 'A period of time from the past to now takes the present perfect continuous with ''for''.', '{"1": "Present continuous and ''since'' with a period are both wrong.", "2": "''Since'' needs a point in time, not a period.", "3": "Simple present with ''from'' is wrong here."}'),
  ('ENG-0459', 'English', 'Sentence correction and spelling', 'Choosing the correct sentence', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 3.1', 'Which sentence is correct?', '["I look forward to hear from you.", "I look forward to hearing from you.", "I look forward for hearing from you.", "I am looking forward to hear from you."]', 1, 'In ''look forward to'', ''to'' is a preposition, so it is followed by a gerund.', '{"0": "''To'' here is a preposition and needs a gerund.", "2": "The fixed phrase is ''look forward to''.", "3": "''To'' here needs a gerund, not the base form."}'),
  ('ENG-0460', 'English', 'Sentence correction and spelling', 'Choosing the correct sentence', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 3.1', 'Which sentence is correct?', '["Neither the teacher or the students were aware of the change.", "Neither the teacher nor the students was aware of the change.", "Neither the teacher nor the students were aware of the change.", "Neither the teacher nor the students were aware about the change."]', 2, '''Neither'' pairs with ''nor'', the verb agrees with the nearer subject ''students'', and ''aware'' takes ''of''.', '{"0": "''Neither'' must pair with ''nor''.", "1": "The nearer subject ''students'' is plural.", "3": "The correct phrase is ''aware of''."}'),
  ('ENG-0461', 'English', 'Sentence correction and spelling', 'Faulty comparison', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 3.1', 'Which sentence is correct?', '["She prefers walking than driving.", "She prefers walking from driving.", "She prefers walking over to driving.", "She prefers walking to driving."]', 3, '''Prefer A to B'' is the standard pattern.', '{"0": "''Prefer ... than'' is a common error.", "1": "''Prefer ... from'' is wrong.", "2": "''Over to'' is not part of this pattern."}'),
  ('ENG-0462', 'English', 'Sentence correction and spelling', 'Faulty comparison', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 3.1', 'Which sentence is correct?', '["The climate of Murree is cooler than that of Lahore.", "The climate of Murree is cooler than Lahore.", "The climate of Murree is more cooler than that of Lahore.", "The climate of Murree is coolest than that of Lahore."]', 0, 'Climate must be compared with climate (''that of Lahore''), not with the city itself.', '{"1": "This compares a climate with a city.", "2": "''More cooler'' is a double comparative.", "3": "A superlative cannot be followed by ''than''."}'),
  ('ENG-0463', 'English', 'Sentence correction and spelling', 'Parallel structure', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 3.1', 'Which sentence is correct?', '["The new doctor is kind, patient and has skill.", "The new doctor is kind, patient and skilled.", "The new doctor is kind, has patience and skilled.", "The new doctor is kind, patiently and skilled."]', 1, 'Items in a list should have the same grammatical form; here, three adjectives.', '{"0": "''Has skill'' breaks the pattern of adjectives.", "2": "''Has patience'' breaks the pattern of adjectives.", "3": "''Patiently'' is an adverb, not an adjective."}'),
  ('ENG-0464', 'English', 'Sentence correction and spelling', 'Double negatives', 'easy', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 3.1', 'Which sentence is correct?', '["I couldn''t hardly hear him.", "I could not hardly hear him.", "I could hardly hear him.", "I hardly couldn''t hear him."]', 2, '''Hardly'' is already negative in meaning, so adding ''not'' makes a double negative.', '{"0": "''Couldn''t hardly'' is a double negative.", "1": "''Not hardly'' is a double negative.", "3": "This is a double negative with odd word order."}'),
  ('ENG-0465', 'English', 'Sentence correction and spelling', 'Articles', 'easy', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 3.1', 'Which sentence is correct?', '["She waited for a hour at the clinic.", "She waited for hour at the clinic.", "She waited for the an hour at the clinic.", "She waited for an hour at the clinic."]', 3, '''Hour'' begins with a vowel sound (the h is silent), so it takes ''an''.', '{"0": "''A'' is used before consonant sounds; ''hour'' begins with a vowel sound.", "1": "A singular countable noun needs an article.", "2": "Two articles cannot be used together."}'),
  ('ENG-0466', 'English', 'Sentence correction and spelling', 'Articles', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 3.1', 'Which sentence is correct?', '["She is a European doctor.", "She is an European doctor.", "She is European a doctor.", "She is European doctor."]', 0, '''European'' begins with a ''y'' consonant sound, so it takes ''a''.', '{"1": "''An'' is used before vowel sounds; ''European'' begins with a ''yoo'' sound.", "2": "The article is in the wrong place.", "3": "A singular countable noun needs an article."}'),
  ('ENG-0467', 'English', 'Sentence correction and spelling', 'Word order', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 3.1', 'Which sentence is correct?', '["Please tell me where is the pharmacy.", "Please tell me where the pharmacy is.", "Please tell me where the pharmacy is?", "Please tell me where does the pharmacy is."]', 1, 'In an embedded question, statement word order is used and the sentence ends with a full stop.', '{"0": "Question word order is wrong inside a statement.", "2": "The sentence is a request, not a direct question, so no question mark.", "3": "''Does ... is'' is ungrammatical."}'),
  ('ENG-0468', 'English', 'Sentence correction and spelling', 'Spotting the error', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 3.2', 'Which part of the sentence contains an error?
(A) The number of (B) students who (C) has passed (D) is very small.', '["(A) The number of", "(B) students who", "(C) has passed", "(D) is very small."]', 2, 'The relative clause ''who ___ passed'' refers to the plural ''students'', so it should be ''have passed''.', '{"0": "''The number of'' is correct; it takes a singular main verb.", "1": "''Students who'' is correct.", "3": "''Is very small'' agrees with ''the number''."}'),
  ('ENG-0469', 'English', 'Sentence correction and spelling', 'Spotting the error', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 3.2', 'Which part of the sentence contains an error?
(A) Each of the (B) doctors have (C) a separate (D) consulting room.', '["(A) Each of the", "(B) doctors have", "(C) a separate", "(D) consulting room."]', 1, '''Each'' is singular, so the verb should be ''has'', not ''have''.', '{"0": "''Each of the'' is correct.", "2": "''A separate'' is correct.", "3": "''Consulting room'' is correct."}'),
  ('ENG-0470', 'English', 'Sentence correction and spelling', 'Spotting the error', 'easy', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 3.2', 'Which part of the sentence contains an error?
(A) She did not (B) went to college (C) yesterday because (D) she was ill.', '["(A) She did not", "(B) went to college", "(C) yesterday because", "(D) she was ill."]', 1, 'After ''did not'', the base form is used: ''did not go''.', '{"0": "''She did not'' is correct.", "2": "''Yesterday because'' is correct.", "3": "''She was ill'' is correct."}'),
  ('ENG-0471', 'English', 'Sentence correction and spelling', 'Spotting the error', 'easy', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 3.2', 'Which part of the sentence contains an error?
(A) He is (B) one of the (C) most cleverest (D) students in the class.', '["(A) He is", "(B) one of the", "(C) most cleverest", "(D) students in the class."]', 2, '''Most cleverest'' is a double superlative; it should be ''cleverest'' or ''most clever''.', '{"0": "''He is'' is correct.", "1": "''One of the'' is correct before a superlative and plural noun.", "3": "''Students in the class'' is correct."}'),
  ('ENG-0472', 'English', 'Sentence correction and spelling', 'Spotting the error', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 3.2', 'Which part of the sentence contains an error?
(A) She has (B) lived in Quetta (C) since (D) five years.', '["(A) She has", "(B) lived in Quetta", "(C) since", "(D) five years."]', 2, 'A length of time takes ''for'', not ''since'': ''for five years''.', '{"0": "''She has'' is correct.", "1": "''Lived in Quetta'' is correct.", "3": "''Five years'' is correct once ''for'' is used."}'),
  ('ENG-0473', 'English', 'Sentence correction and spelling', 'Spotting the error', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, English learning outcome 3.2', 'Which part of the sentence contains an error?
(A) The furnitures (B) for the new ward (C) arrived (D) last week.', '["(A) The furnitures", "(B) for the new ward", "(C) arrived", "(D) last week."]', 0, '''Furniture'' is uncountable and has no plural form; it should be ''The furniture''.', '{"1": "''For the new ward'' is correct.", "2": "''Arrived'' is correct simple past.", "3": "''Last week'' is correct."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10, s.column11,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('LR-0137', 'Logical Reasoning', 'Critical thinking', 'Assumptions', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.1', '"We should open a new medical college in this district, because the district has a shortage of doctors."
Which assumption does this argument depend on?', '["Medical colleges are cheap to build", "The district has no hospitals", "Doctors trained in the district are likely to stay and work there", "Every student wants to become a doctor"]', 2, 'Training doctors locally fixes the local shortage only if the new doctors stay and work in the district.', '{"0": "The argument says nothing about cost.", "1": "The argument is about doctors, not hospitals.", "3": "The argument does not need every student to want medicine."}'),
  ('LR-0138', 'Logical Reasoning', 'Critical thinking', 'Assumptions', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.1', '"Our new advertisement must be working: sales went up by 20% this month."
Which assumption does this argument depend on?', '["Advertisements are always expensive", "Sales will keep rising every month", "Customers dislike advertisements", "Nothing else caused the rise in sales this month"]', 3, 'The argument credits the advertisement, which only works if no other factor (a festival season, a price cut) explains the rise.', '{"0": "Cost is irrelevant to whether the advertisement worked.", "1": "The argument is about this month, not the future.", "2": "This would weaken, not support, the argument."}'),
  ('LR-0139', 'Logical Reasoning', 'Critical thinking', 'Strengthening an argument', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.1', '"Drinking green tea lowers blood pressure."
Which finding would most STRENGTHEN this claim?', '["In a controlled trial, people randomly given green tea had lower blood pressure than those given water", "Green tea is popular in China", "Some people who drink green tea also exercise", "Green tea costs more than black tea"]', 0, 'A randomised controlled trial separates the effect of the tea from other factors, so it gives the strongest support.', '{"1": "Popularity says nothing about blood pressure.", "2": "Exercise is another possible cause, which weakens the claim.", "3": "Price is irrelevant."}'),
  ('LR-0140', 'Logical Reasoning', 'Critical thinking', 'Weakening an argument', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.1', '"Students who attend tuition academies score higher in MDCAT, so tuition academies improve scores."
Which fact, if true, most WEAKENS this conclusion?', '["Academies charge monthly fees", "Students who join academies already had higher marks before joining", "Some academies are in large cities", "MDCAT has 200 questions"]', 1, 'If academy students were already stronger, their higher scores may reflect ability, not the academy.', '{"0": "Fees do not affect whether academies raise scores.", "2": "Location does not challenge the causal claim.", "3": "The number of questions is irrelevant."}'),
  ('LR-0141', 'Logical Reasoning', 'Critical thinking', 'Fact and opinion', 'easy', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.1', 'Which of these is an OPINION rather than a fact?', '["The heart has four chambers.", "Insulin is produced by the pancreas.", "Surgery is the most rewarding branch of medicine.", "Pakistan has four provinces."]', 2, '''Most rewarding'' is a personal judgement that cannot be proved; the others can be checked.', '{"0": "This can be checked in any anatomy book.", "1": "This is an established biological fact.", "3": "This can be checked."}'),
  ('LR-0142', 'Logical Reasoning', 'Critical thinking', 'Arguments and conclusions', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.1', '"All the samples were kept in the fridge. This sample has gone bad, so the fridge must not be working."
What is the conclusion of this argument?', '["All the samples were kept in the fridge", "This sample has gone bad", "Samples go bad outside the fridge", "The fridge is not working"]', 3, 'The conclusion is the claim that the reasons are meant to support; it follows ''so''.', '{"0": "This is a premise (a reason).", "1": "This is a premise (a reason).", "2": "This is not stated in the argument."}'),
  ('LR-0143', 'Logical Reasoning', 'Critical thinking', 'Necessary and sufficient conditions', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.1', '"Passing MDCAT is necessary for admission to a medical college."
Which statement must be true?', '["A student admitted to a medical college has passed MDCAT", "Every student who passes MDCAT gets admission", "A student who fails MDCAT may still be admitted", "Passing MDCAT is the only requirement for admission"]', 0, 'A necessary condition must be met by everyone admitted, so anyone admitted has passed. It does not guarantee admission.', '{"1": "That would make passing sufficient, not just necessary.", "2": "This contradicts the statement.", "3": "''Necessary'' does not mean ''the only requirement''."}'),
  ('LR-0144', 'Logical Reasoning', 'Critical thinking', 'Logical fallacies', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.1', '"I wore my lucky shirt and our team won. I must wear it to every match."
This reasoning is flawed because it:', '["attacks a person instead of an argument", "assumes that one event caused another just because it came first", "relies on the opinion of an expert", "offers only two choices"]', 1, 'Winning after wearing the shirt does not show the shirt caused the win (the ''after this, therefore because of this'' fallacy).', '{"0": "No one is attacked.", "2": "No expert is quoted.", "3": "No choice between two options is forced."}'),
  ('LR-0145', 'Logical Reasoning', 'Critical thinking', 'Logical fallacies', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.1', '"Everyone in my class is buying this guidebook, so it must be the best one."
This reasoning is an example of:', '["a straw man", "circular reasoning", "an appeal to popularity", "a slippery slope"]', 2, 'Claiming something is best because many people choose it is an appeal to popularity (bandwagon).', '{"0": "No one''s argument is distorted.", "1": "The conclusion is not used as its own reason.", "3": "No chain of bad consequences is described."}'),
  ('LR-0146', 'Logical Reasoning', 'Critical thinking', 'Evaluating evidence', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.1', 'A newspaper reports that a herbal drink cures diabetes. The only evidence is a statement from the company that sells the drink.
What is the main weakness of this evidence?', '["Newspapers never print health news", "Diabetes cannot be treated", "Herbal drinks are always harmful", "The source has a financial interest in the claim"]', 3, 'A seller benefits from people believing the claim, so the evidence is biased; independent trials are needed.', '{"0": "Newspapers often print health news; that is not the issue.", "1": "Diabetes can be treated; the issue is the evidence.", "2": "This is an overgeneralisation and not the weakness."}'),
  ('LR-0147', 'Logical Reasoning', 'Critical thinking', 'True and false beliefs', 'easy', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.1', 'Statement: "All birds can fly."
Which single fact shows this statement is FALSE?', '["Ostriches are birds that cannot fly", "Sparrows can fly", "Bats can fly", "Some birds fly south in winter"]', 0, 'One counter-example (a bird that cannot fly) is enough to disprove an ''all'' statement.', '{"1": "Sparrows fit the statement, so they do not disprove it.", "2": "Bats are mammals, so they are irrelevant.", "3": "Migration does not challenge the statement."}'),
  ('LR-0148', 'Logical Reasoning', 'Critical thinking', 'Drawing inferences', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.1', '"The library is open only on weekdays. Today Sana found the library open."
What can be concluded?', '["Today is Saturday", "Today is a weekday", "Sana works in the library", "The library is open every day"]', 1, 'If it opens only on weekdays and it is open today, today must be a weekday.', '{"0": "The library is not open on Saturday.", "2": "Nothing says Sana works there.", "3": "This contradicts ''only on weekdays''."}'),
  ('LR-0149', 'Logical Reasoning', 'Critical thinking', 'Drawing inferences', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.1', '"No student who failed the practical passed the course. Ahmed passed the course."
Which conclusion follows?', '["Ahmed scored full marks in the practical", "Ahmed failed the theory paper", "Ahmed did not fail the practical", "Everyone who passed the practical passed the course"]', 2, 'If failing the practical rules out passing the course, anyone who passed the course did not fail the practical.', '{"0": "Not failing does not mean full marks.", "1": "Nothing is said about the theory paper.", "3": "Passing the practical may not be enough to pass the course."}'),
  ('LR-0150', 'Logical Reasoning', 'Patterns and sequences', 'Number series', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2', 'What comes next in the series?
5, 11, 23, 47, ?', '["94", "71", "96", "95"]', 3, 'Each term is double the previous plus 1: 47 × 2 + 1 = 95.', '{"0": "94 is 47 × 2 without adding 1.", "1": "71 adds 24; the gaps double each time.", "2": "96 is 47 × 2 + 2."}'),
  ('LR-0151', 'Logical Reasoning', 'Patterns and sequences', 'Number series', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2', 'What comes next in the series?
2, 9, 28, 65, ?', '["126", "125", "100", "129"]', 0, 'Each term is a cube plus 1: 1³+1, 2³+1, 3³+1, 4³+1, so next is 5³ + 1 = 126.', '{"1": "125 is 5³ without adding 1.", "2": "100 does not follow the cube pattern.", "3": "129 adds 64 to 65 instead of using the rule."}'),
  ('LR-0152', 'Logical Reasoning', 'Patterns and sequences', 'Number series', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2', 'What comes next in the series?
4, 6, 10, 14, 22, 26, ?', '["30", "34", "28", "38"]', 1, 'These are double the prime numbers: 2×2, 2×3, 2×5, 2×7, 2×11, 2×13, so next is 2 × 17 = 34.', '{"0": "30 = 2 × 15, and 15 is not prime.", "2": "28 = 2 × 14, and 14 is not prime.", "3": "38 = 2 × 19 skips the prime 17."}'),
  ('LR-0153', 'Logical Reasoning', 'Patterns and sequences', 'Number series', 'easy', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2', 'What comes next in the series?
2, 3, 5, 8, 12, ?', '["16", "18", "17", "20"]', 2, 'The differences are 1, 2, 3, 4, so next add 5: 12 + 5 = 17.', '{"0": "16 adds 4 again.", "1": "18 adds 6.", "3": "20 adds 8."}'),
  ('LR-0154', 'Logical Reasoning', 'Patterns and sequences', 'Number series', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2', 'What comes next in the series?
100, 96, 88, 76, 60, ?', '["44", "36", "50", "40"]', 3, 'The differences are 4, 8, 12, 16, so next subtract 20: 60 − 20 = 40.', '{"0": "44 subtracts 16 again.", "1": "36 subtracts 24.", "2": "50 subtracts 10."}'),
  ('LR-0155', 'Logical Reasoning', 'Patterns and sequences', 'Number series', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2', 'What comes next in the series?
3, 6, 11, 18, 27, ?', '["38", "36", "39", "40"]', 0, 'The differences are 3, 5, 7, 9 (odd numbers), so next add 11: 27 + 11 = 38.', '{"1": "36 adds 9 again.", "2": "39 adds 12.", "3": "40 adds 13."}'),
  ('LR-0156', 'Logical Reasoning', 'Patterns and sequences', 'Number series', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2', 'What comes next in the series?
2, 5, 4, 7, 6, 9, ?', '["11", "8", "10", "12"]', 1, 'The pattern alternates +3, −1: 2, 5, 4, 7, 6, 9, so next is 9 − 1 = 8.', '{"0": "11 adds 2.", "2": "10 adds 1.", "3": "12 adds 3, but the +3 step has just been used."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10, s.column11,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('LR-0157', 'Logical Reasoning', 'Patterns and sequences', 'Number series', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2', 'What comes next in the series?
7, 14, 42, 168, ?', '["336", "672", "840", "1008"]', 2, 'Multiply by 2, 3, 4, then 5: 168 × 5 = 840.', '{"0": "336 multiplies by 2.", "1": "672 multiplies by 4 again.", "3": "1008 multiplies by 6."}'),
  ('LR-0158', 'Logical Reasoning', 'Patterns and sequences', 'Letter series', 'easy', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2', 'What comes next in the series?
D, G, J, M, P, ?', '["R", "T", "Q", "S"]', 3, 'Each letter moves 3 places forward: P (16) + 3 = S (19).', '{"0": "R is P + 2.", "1": "T is P + 4.", "2": "Q is P + 1."}'),
  ('LR-0159', 'Logical Reasoning', 'Patterns and sequences', 'Letter series', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2', 'What comes next in the series?
A, Z, B, Y, C, X, ?', '["D", "W", "E", "V"]', 0, 'Two series alternate: A, B, C, ... going forward and Z, Y, X, ... going back. The next letter belongs to the forward series: D.', '{"1": "W is the next letter of the backward series, but it is the forward series'' turn.", "2": "E skips D.", "3": "V skips W in the backward series and is also out of turn."}'),
  ('LR-0160', 'Logical Reasoning', 'Patterns and sequences', 'Letter series', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2', 'What comes next in the series?
Y, W, T, P, ?', '["L", "K", "J", "M"]', 1, 'The letters move back by 2, 3, 4, then 5: P (16) − 5 = K (11).', '{"0": "L is P − 4; the step should grow.", "2": "J is P − 6.", "3": "M is P − 3."}'),
  ('LR-0161', 'Logical Reasoning', 'Patterns and sequences', 'Letter series', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2', 'What comes next in the series?
AB, CD, EF, GH, ?', '["HI", "IK", "IJ", "JK"]', 2, 'Each pair is the next two letters of the alphabet: after G and H come I and J.', '{"0": "HI repeats H.", "1": "The second letter should follow I directly.", "3": "JK skips I."}'),
  ('LR-0162', 'Logical Reasoning', 'Patterns and sequences', 'Letter series', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2', 'What comes next in the series?
2B, 4D, 6F, 8H, ?', '["10I", "9J", "12J", "10J"]', 3, 'The number goes up by 2 each time, and the letter is the one at that position in the alphabet: 10th letter is J.', '{"0": "I is the 9th letter, not the 10th.", "1": "The numbers rise by 2, so 9 is wrong.", "2": "12 skips 10."}'),
  ('LR-0163', 'Logical Reasoning', 'Patterns and sequences', 'Coding', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2', 'In a code, CAT is written as 24 because C (3) + A (1) + T (20) = 24.
Using the same rule, how is DOG written?', '["26", "24", "27", "25"]', 0, 'Using letter positions: D = 4, O = 15, G = 7, and 4 + 15 + 7 = 26.', '{"1": "24 is the code for CAT.", "2": "27 adds an extra 1.", "3": "25 is one short."}'),
  ('LR-0164', 'Logical Reasoning', 'Patterns and sequences', 'Coding', 'easy', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2', 'In a code, BOOK is written as DQQM.
How is PEN written in the same code?', '["QFO", "RGP", "RGO", "SHQ"]', 1, 'Each letter moves 2 places forward: P → R, E → G, N → P.', '{"0": "This moves each letter only 1 place.", "2": "N should become P, not O.", "3": "This moves each letter 3 places."}'),
  ('LR-0165', 'Logical Reasoning', 'Patterns and sequences', 'Odd one out', 'easy', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2', 'Which number is the odd one out?
16, 25, 27, 36', '["16", "25", "27", "36"]', 2, '16, 25 and 36 are perfect squares; 27 is a cube (3³), not a square.', '{"0": "16 = 4² is a square.", "1": "25 = 5² is a square.", "3": "36 = 6² is a square."}'),
  ('LR-0166', 'Logical Reasoning', 'Patterns and sequences', 'Odd one out', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2', 'Which word is the odd one out?
Femur, Tibia, Kidney, Humerus', '["Femur", "Tibia", "Humerus", "Kidney"]', 3, 'Femur, tibia and humerus are bones; the kidney is an organ.', '{"0": "The femur is a bone, like the others.", "1": "The tibia is a bone, like the others.", "2": "The humerus is a bone, like the others."}'),
  ('LR-0167', 'Logical Reasoning', 'Patterns and sequences', 'Analogy', 'easy', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2', 'Heart is to circulation as ______ is to respiration.', '["Lungs", "Liver", "Bones", "Skin"]', 0, 'The heart is the main organ of the circulatory system; the lungs are the main organs of the respiratory system.', '{"1": "The liver belongs mainly to the digestive system.", "2": "Bones belong to the skeletal system.", "3": "Skin belongs to the integumentary system."}'),
  ('LR-0168', 'Logical Reasoning', 'Patterns and sequences', 'Analogy', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2', 'Cardiologist is to heart as ______ is to birds.', '["Botanist", "Ornithologist", "Entomologist", "Zoologist"]', 1, 'A cardiologist specialises in the heart; an ornithologist specialises in birds.', '{"0": "A botanist studies plants.", "2": "An entomologist studies insects.", "3": "A zoologist studies animals in general."}'),
  ('LR-0169', 'Logical Reasoning', 'Logical deductions', 'Syllogisms', 'easy', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3', 'Statement 1: All doctors are graduates.
Statement 2: All surgeons are doctors.
Conclusion I: All surgeons are graduates.
Conclusion II: All graduates are surgeons.
Which conclusion(s) follow?', '["Only conclusion I follows", "Only conclusion II follows", "Both conclusions follow", "Neither conclusion follows"]', 0, 'Surgeons ⊂ doctors ⊂ graduates, so all surgeons are graduates. Graduates may include many who are not surgeons.', '{"1": "II reverses the relationship and does not follow.", "2": "II does not follow.", "3": "I follows directly."}'),
  ('LR-0170', 'Logical Reasoning', 'Logical deductions', 'Syllogisms', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3', 'Statement 1: Some students are athletes.
Statement 2: All athletes are healthy.
Conclusion I: Some students are healthy.
Conclusion II: All students are healthy.
Which conclusion(s) follow?', '["Only conclusion I follows", "Only conclusion II follows", "Both conclusions follow", "Neither conclusion follows"]', 0, 'The students who are athletes are healthy, so some students are healthy. Nothing is known about the other students.', '{"1": "II overgeneralises to all students.", "2": "II does not follow.", "3": "I follows."}'),
  ('LR-0171', 'Logical Reasoning', 'Logical deductions', 'Syllogisms', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3', 'Statement 1: No fish is a mammal.
Statement 2: All whales are mammals.
Conclusion I: No whale is a fish.
Conclusion II: Some fish are whales.
Which conclusion(s) follow?', '["Only conclusion I follows", "Only conclusion II follows", "Both conclusions follow", "Neither conclusion follows"]', 0, 'Whales are inside ''mammals'', which has no overlap with fish, so no whale is a fish. II contradicts this.', '{"1": "II contradicts I.", "2": "II does not follow.", "3": "I follows."}'),
  ('LR-0172', 'Logical Reasoning', 'Logical deductions', 'Syllogisms', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3', 'Statement 1: Some books are pens.
Statement 2: Some pens are pencils.
Conclusion I: Some books are pencils.
Conclusion II: No book is a pencil.
Which conclusion(s) follow?', '["Only conclusion I follows", "Only conclusion II follows", "Both conclusions follow", "Neither conclusion follows"]', 3, 'Two ''some'' statements give no definite link between books and pencils, so neither conclusion is certain.', '{"0": "The books that are pens need not be the pens that are pencils.", "1": "It is possible that some books are pencils.", "2": "The two conclusions contradict each other."}'),
  ('LR-0173', 'Logical Reasoning', 'Logical deductions', 'Syllogisms', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3', 'Statement 1: All roses are flowers.
Statement 2: Some flowers fade quickly.
Conclusion I: Some roses fade quickly.
Conclusion II: All flowers are roses.
Which conclusion(s) follow?', '["Only conclusion I follows", "Only conclusion II follows", "Both conclusions follow", "Neither conclusion follows"]', 3, 'The flowers that fade quickly may or may not be roses, and ''all roses are flowers'' does not reverse.', '{"0": "The quickly fading flowers might not include any roses.", "1": "Many flowers are not roses.", "2": "Neither follows."}'),
  ('LR-0174', 'Logical Reasoning', 'Logical deductions', 'Statements and conclusions', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3', 'Statement: "The hospital has announced free eye check-ups for everyone over 60 this Sunday."
Which conclusion follows?', '["The hospital has too many eye doctors", "People under 60 have healthy eyes", "People over 60 can have their eyes checked without paying this Sunday", "Eye check-ups are free every Sunday"]', 2, 'The statement directly says check-ups are free this Sunday for those over 60.', '{"0": "The number of doctors is not mentioned.", "1": "Nothing is said about the eyes of younger people.", "3": "The offer is for ''this Sunday'' only."}'),
  ('LR-0175', 'Logical Reasoning', 'Logical deductions', 'Blood relations', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3', 'Pointing to a woman, Ali says, "She is the only daughter of my mother''s father."
How is the woman related to Ali?', '["Aunt", "Sister", "Grandmother", "Mother"]', 3, 'The only daughter of Ali''s mother''s father is Ali''s mother herself.', '{"0": "An aunt would be another daughter, but the woman is the only daughter.", "1": "A sister would be the daughter of Ali''s mother.", "2": "A grandmother would be the wife of his mother''s father."}'),
  ('LR-0176', 'Logical Reasoning', 'Logical deductions', 'Blood relations', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3', 'A is the brother of B. B is the sister of C. C is the father of D.
How is A related to D?', '["Uncle", "Father", "Brother", "Grandfather"]', 0, 'A, B and C are siblings. C is D''s father, so A (a male sibling of C) is D''s uncle.', '{"1": "C is the father, not A.", "2": "A is a generation above D.", "3": "A is C''s brother, not his father."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10, s.column11,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('LR-0177', 'Logical Reasoning', 'Logical deductions', 'Conditional reasoning', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3', '"If the patient''s temperature is above 38 °C, the nurse calls the doctor." The nurse did not call the doctor.
What can be concluded?', '["The patient''s temperature was above 38 °C", "The patient''s temperature was not above 38 °C", "The doctor was busy", "The nurse forgot"]', 1, 'If P then Q; not Q, so not P. The temperature could not have been above 38 °C.', '{"0": "This contradicts the rule.", "2": "The rule says nothing about the doctor being busy.", "3": "The rule, taken as true, does not allow for forgetting."}'),
  ('LR-0178', 'Logical Reasoning', 'Logical deductions', 'Conditional reasoning', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3', '"If it rains, the match is cancelled." The match was cancelled.
What can be concluded?', '["It rained", "It did not rain", "Nothing certain about whether it rained", "The match will be played tomorrow"]', 2, 'The match could have been cancelled for another reason, so the cancellation does not prove it rained (affirming the consequent).', '{"0": "Rain is one possible cause, not the only one.", "1": "It might have rained.", "3": "Nothing is said about tomorrow."}'),
  ('LR-0179', 'Logical Reasoning', 'Logical deductions', 'Ordering', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3', 'Bilal is older than Hamza but younger than Usman. Usman is younger than Zain.
Who is the oldest?', '["Usman", "Bilal", "Hamza", "Zain"]', 3, 'Hamza < Bilal < Usman < Zain, so Zain is the oldest.', '{"0": "Usman is younger than Zain.", "1": "Bilal is younger than Usman.", "2": "Hamza is the youngest."}'),
  ('LR-0180', 'Logical Reasoning', 'Logical deductions', 'Ranking', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3', 'In a class of 40 students, Bilal is 12th from the top.
What is his rank from the bottom?', '["29th", "28th", "30th", "27th"]', 0, 'Rank from bottom = total − rank from top + 1 = 40 − 12 + 1 = 29.', '{"1": "28 forgets to add 1.", "2": "30 adds 2.", "3": "27 subtracts 1."}'),
  ('LR-0181', 'Logical Reasoning', 'Logical problems', 'Direction problems', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4', 'Ahmed walks 5 km north, then 3 km east, then 9 km south.
How far is he from his starting point?', '["7 km", "5 km", "4 km", "17 km"]', 1, 'He ends 3 km east and 4 km south of the start. By Pythagoras, √(3² + 4²) = 5 km.', '{"0": "7 km adds 3 and 4 instead of using Pythagoras.", "2": "4 km is only the north-south distance.", "3": "17 km is the total distance walked."}'),
  ('LR-0182', 'Logical Reasoning', 'Logical problems', 'Direction problems', 'easy', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4', 'Facing north, Sana turns right, then right again, then left.
Which direction is she facing now?', '["West", "North", "East", "South"]', 2, 'North → right → East → right → South → left → East.', '{"0": "She would face west only after a different set of turns.", "1": "She faces north only at the start.", "3": "South is where she faces after the second turn, before turning left."}'),
  ('LR-0183', 'Logical Reasoning', 'Logical problems', 'Clock problems', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4', 'What is the angle between the hour hand and the minute hand at 3:30?', '["90°", "60°", "105°", "75°"]', 3, 'At 3:30 the minute hand is at 180°. The hour hand is at 90° + half of 30° = 105°. The angle is 180° − 105° = 75°.', '{"0": "90° is the angle at 3:00.", "1": "60° does not match the hands'' positions at 3:30.", "2": "105° is the hour hand''s position, not the angle between hands."}'),
  ('LR-0184', 'Logical Reasoning', 'Logical problems', 'Calendar problems', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4', 'If 5 March is a Tuesday, what day of the week is 26 March of the same year?', '["Tuesday", "Monday", "Wednesday", "Sunday"]', 0, '26 − 5 = 21 days, which is exactly 3 weeks, so it is the same day: Tuesday.', '{"1": "That would need 20 days.", "2": "That would need 22 days.", "3": "That would need 19 days."}'),
  ('LR-0185', 'Logical Reasoning', 'Logical problems', 'Age problems', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4', 'In 2 years, Hamza will be twice as old as his sister, who is 7 now.
How old is Hamza now?', '["14", "16", "18", "12"]', 1, 'In 2 years the sister will be 9, so Hamza will be 18. Now he is 18 − 2 = 16.', '{"0": "14 is twice her present age.", "2": "18 is his age in two years.", "3": "12 does not satisfy the condition."}'),
  ('LR-0186', 'Logical Reasoning', 'Logical problems', 'Sets and groups', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4', 'In a group of 30 students, 18 like biology, 15 like chemistry and 5 like neither.
How many like both?', '["3", "5", "8", "13"]', 2, '25 students like at least one subject. 18 + 15 = 33, so 33 − 25 = 8 are counted twice and like both.', '{"0": "3 is 18 − 15.", "1": "5 is the number who like neither.", "3": "13 forgets to subtract those who like neither."}'),
  ('LR-0187', 'Logical Reasoning', 'Logical problems', 'Counting problems', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4', 'How many diagonals does a hexagon (six-sided figure) have?', '["6", "12", "15", "9"]', 3, 'A polygon with n sides has n(n − 3) ÷ 2 diagonals: 6 × 3 ÷ 2 = 9.', '{"0": "6 is the number of sides.", "1": "12 does not follow the formula n(n − 3) ÷ 2.", "2": "15 counts all lines joining pairs of corners, including the 6 sides."}'),
  ('LR-0188', 'Logical Reasoning', 'Logical problems', 'Counting problems', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4', 'How many squares of all sizes are there on a 4 × 4 grid of small squares?', '["30", "16", "20", "25"]', 0, '1 × 1: 16, 2 × 2: 9, 3 × 3: 4, 4 × 4: 1. Total 16 + 9 + 4 + 1 = 30.', '{"1": "16 counts only the smallest squares.", "2": "20 misses the 2 × 2 squares.", "3": "25 misses the 3 × 3 and 4 × 4 squares."}'),
  ('LR-0189', 'Logical Reasoning', 'Logical problems', 'Truth and lies', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4', 'Each of A, B and C either always tells the truth or always lies.
A says: "B is a liar."
B says: "C is a liar."
C says: "A and B are both liars."
Who tells the truth?', '["Only A", "Only B", "Only C", "A and C"]', 1, 'Suppose C tells the truth. Then A and B both lie, but A''s statement ''B is a liar'' would then be true, a contradiction. So C lies. Then B''s statement ''C is a liar'' is true, so B tells the truth, and A''s statement ''B is a liar'' is false, so A lies. Check: C''s claim is false because B is truthful.', '{"0": "A''s claim that B lies is false, because B tells the truth.", "2": "C''s claim is false, since B is not a liar.", "3": "Both A and C make false claims."}'),
  ('LR-0190', 'Logical Reasoning', 'Logical problems', 'Ordering puzzles', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4', 'Five runners, P, Q, R, S and T, finish a race. T finishes first. P finishes before Q. Q finishes before S. S finishes before R.
Who finishes third?', '["P", "S", "Q", "R"]', 2, 'T is first, and P, Q, S, R must follow in that order: T, P, Q, S, R. Q is third.', '{"0": "P is second.", "1": "S is fourth.", "3": "R is last."}'),
  ('LR-0191', 'Logical Reasoning', 'Logical problems', 'Ordering puzzles', 'easy', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4', 'Five runners, P, Q, R, S and T, finish a race. T finishes first. P finishes before Q. Q finishes before S. S finishes before R.
Who finishes last?', '["S", "Q", "P", "R"]', 3, 'The order is T, P, Q, S, R, so R is last.', '{"0": "S is fourth.", "1": "Q is third.", "2": "P is second."}'),
  ('LR-0192', 'Logical Reasoning', 'Logical problems', 'Seating arrangement', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4', 'Six friends, A, B, C, D, E and F, sit around a round table facing the centre. A sits opposite D. B sits immediately to A''s right. C sits opposite B. E sits immediately to D''s left.
Who sits opposite F?', '["E", "A", "B", "C"]', 0, 'Number the seats 1 to 6 around the table, with A in seat 1, so D (opposite) is in seat 4. B is next to A, say seat 2; then C, opposite B, is in seat 5, next to D. E is next to D on the other side, seat 3. F takes the last seat, 6, which is opposite seat 3: E. (Mirroring the table gives the same pairs.)', '{"1": "A sits opposite D.", "2": "B sits opposite C.", "3": "C sits opposite B."}'),
  ('LR-0193', 'Logical Reasoning', 'Logical problems', 'Code language', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4', 'In a code language, "sky is blue" is written "ta na ri" and "blue sea" is written "ri lo".
Which code means "blue"?', '["ta", "ri", "na", "lo"]', 1, '''Blue'' is the only word in both phrases, and ''ri'' is the only code in both.', '{"0": "''Ta'' appears only in the first phrase.", "2": "''Na'' appears only in the first phrase.", "3": "''Lo'' must mean ''sea''."}'),
  ('LR-0194', 'Logical Reasoning', 'Course of action', 'Courses of action', 'easy', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5', 'Statement: A large crack has appeared in the wall of an old school building.
Course of action I: Engineers should inspect the building to check whether it is safe.
Course of action II: Students should be kept out of the damaged part until it is checked.
Which course(s) of action logically follow?', '["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"]', 2, 'An inspection finds out how serious the damage is, and keeping students away protects them meanwhile. Both are sensible.', '{"0": "II is also needed to keep students safe.", "1": "I is also needed to judge the damage.", "3": "Both steps are reasonable."}'),
  ('LR-0195', 'Logical Reasoning', 'Course of action', 'Courses of action', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5', 'Statement: Many students in a college hostel have complained of stomach upsets after meals.
Course of action I: The hostel kitchen and water supply should be checked for contamination.
Course of action II: The hostel should be closed permanently.
Which course(s) of action logically follow?', '["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"]', 0, 'Checking the kitchen and water tackles the likely cause. Closing the hostel permanently is extreme.', '{"1": "Permanent closure is out of proportion.", "2": "II does not follow.", "3": "I is a practical step."}'),
  ('LR-0196', 'Logical Reasoning', 'Course of action', 'Courses of action', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5', 'Statement: A new road has many accidents at one sharp bend.
Course of action I: Warning signs and speed limits should be put up near the bend.
Course of action II: All vehicles should be banned from the road.
Which course(s) of action logically follow?', '["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"]', 0, 'Signs and speed limits address the danger at the bend. Banning all vehicles would make the road useless.', '{"1": "A complete ban is extreme.", "2": "II does not follow.", "3": "I is a practical step."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10, s.column11,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('LR-0197', 'Logical Reasoning', 'Course of action', 'Courses of action', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5', 'Statement: A pharmacy was found selling expired medicines.
Course of action I: The pharmacy''s licence should be suspended until an inquiry is completed.
Course of action II: People should stop buying medicines from all pharmacies.
Which course(s) of action logically follow?', '["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"]', 0, 'Suspending this pharmacy protects the public while the facts are checked. Avoiding all pharmacies punishes the many for one offender and would harm patients.', '{"1": "II is an overreaction affecting every pharmacy.", "2": "II does not follow.", "3": "I is a proportionate step."}'),
  ('LR-0198', 'Logical Reasoning', 'Course of action', 'Courses of action', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5', 'Statement: The number of dengue cases in a city has doubled this month.
Course of action I: Fogging and removal of standing water should be stepped up.
Course of action II: Hospitals should prepare extra beds for dengue patients.
Which course(s) of action logically follow?', '["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"]', 2, 'Fogging tackles mosquitoes, and extra beds prepare for the patients. Both are reasonable.', '{"0": "II is also reasonable given the rise in cases.", "1": "I is also reasonable to control spread.", "3": "Both are sensible."}'),
  ('LR-0199', 'Logical Reasoning', 'Course of action', 'Courses of action', 'easy', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5', 'Statement: A student was caught using a mobile phone in the examination hall.
Course of action I: The student should be dealt with according to the examination rules.
Course of action II: Mobile phones should be banned throughout the country.
Which course(s) of action logically follow?', '["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"]', 0, 'Applying the exam rules deals with the case. A nationwide ban is far out of proportion.', '{"1": "A nationwide ban is extreme.", "2": "II does not follow.", "3": "I follows."}'),
  ('LR-0200', 'Logical Reasoning', 'Course of action', 'Courses of action', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5', 'Statement: Teachers report that many first-year students struggle with English used in textbooks.
Course of action I: The college should offer extra English language support classes.
Course of action II: All textbooks should be translated and English should no longer be taught.
Which course(s) of action logically follow?', '["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"]', 0, 'Support classes directly help students cope. Removing English entirely is extreme and would leave students less prepared.', '{"1": "II is extreme.", "2": "II does not follow.", "3": "I is a reasonable step."}'),
  ('LR-0201', 'Logical Reasoning', 'Course of action', 'Courses of action', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5', 'Statement: There is a sudden shortage of a common blood pressure medicine in the market.
Course of action I: The authorities should find out why supply has stopped.
Course of action II: Doctors should guide patients about safe alternatives in the meantime.
Which course(s) of action logically follow?', '["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"]', 2, 'Finding the cause addresses the supply, and advising alternatives protects patients now. Both follow.', '{"0": "II is also needed for patients'' safety.", "1": "I is also needed to fix the supply.", "3": "Both are sensible."}'),
  ('LR-0202', 'Logical Reasoning', 'Course of action', 'Courses of action', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5', 'Statement: A popular website crashed when MDCAT results were announced.
Course of action I: The website''s capacity should be increased before the next result.
Course of action II: Results should no longer be announced online.
Which course(s) of action logically follow?', '["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"]', 0, 'Increasing capacity fixes the problem. Abandoning online results would be an overreaction.', '{"1": "Stopping online results is extreme.", "2": "II does not follow.", "3": "I is practical."}'),
  ('LR-0203', 'Logical Reasoning', 'Course of action', 'Courses of action', 'easy', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5', 'Statement: A gas cylinder exploded in a restaurant kitchen, injuring two workers.
Course of action I: The injured workers should be taken to hospital immediately.
Course of action II: Gas safety in restaurant kitchens should be inspected.
Which course(s) of action logically follow?', '["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"]', 2, 'Treating the injured is urgent, and inspections help prevent similar explosions. Both follow.', '{"0": "II is also needed to prevent repeats.", "1": "I is the immediate need.", "3": "Both follow."}'),
  ('LR-0204', 'Logical Reasoning', 'Course of action', 'Courses of action', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5', 'Statement: Some students in a class scored very low marks in one weekly test.
Course of action I: Those students should be expelled.
Course of action II: The teacher should find out which topics they found difficult.
Which course(s) of action logically follow?', '["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"]', 1, 'One poor test calls for finding the weak areas; expulsion is far too harsh.', '{"0": "Expulsion for one test is extreme.", "2": "I does not follow.", "3": "II is a sensible step."}'),
  ('LR-0205', 'Logical Reasoning', 'Course of action', 'Courses of action', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5', 'Statement: Smoke from brick kilns around a city is causing breathing problems in winter.
Course of action I: Kilns should be required to switch to cleaner technology.
Course of action II: All construction in the country should be stopped.
Which course(s) of action logically follow?', '["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"]', 0, 'Cleaner kiln technology tackles the source of the smoke. Stopping all construction nationwide is far out of proportion.', '{"1": "II is extreme.", "2": "II does not follow.", "3": "I is a practical step."}'),
  ('LR-0206', 'Logical Reasoning', 'Cause and effect', 'Cause and effect pairs', 'easy', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.6', 'Statement I: The college canteen raised its prices.
Statement II: Fewer students bought lunch from the canteen.
What is the relationship between the two statements?', '["Statement I is the cause and Statement II is its effect", "Statement II is the cause and Statement I is its effect", "Both statements are effects of a common cause", "The two statements are not causally related"]', 0, 'Higher prices make students buy less, so I causes II.', '{"1": "Fewer buyers do not make the prices rise.", "2": "The price rise is the direct cause.", "3": "Price and demand are linked."}'),
  ('LR-0207', 'Logical Reasoning', 'Cause and effect', 'Cause and effect pairs', 'easy', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.6', 'Statement I: Many people in the area fell ill with typhoid.
Statement II: A sewage pipe leaked into the drinking water supply.
What is the relationship between the two statements?', '["Statement I is the cause and Statement II is its effect", "Statement II is the cause and Statement I is its effect", "Both statements are effects of a common cause", "The two statements are not causally related"]', 1, 'Contaminated water spreads typhoid, so II causes I.', '{"0": "Illness does not make pipes leak.", "2": "The leak directly explains the illness.", "3": "They are clearly linked."}'),
  ('LR-0208', 'Logical Reasoning', 'Cause and effect', 'Cause and effect pairs', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.6', 'Statement I: Schools in the city were closed for a week.
Statement II: Hospitals reported many heatstroke cases.
What is the relationship between the two statements?', '["Statement I is the cause and Statement II is its effect", "Statement II is the cause and Statement I is its effect", "Both statements are effects of a common cause", "The two statements are not causally related"]', 2, 'Both are likely effects of a common cause: a severe heatwave.', '{"0": "Closing schools does not cause heatstroke.", "1": "Heatstroke in hospitals does not close schools by itself.", "3": "They share a likely cause."}'),
  ('LR-0209', 'Logical Reasoning', 'Cause and effect', 'Cause and effect pairs', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.6', 'Statement I: A famous cricketer opened a new restaurant.
Statement II: The price of gold rose.
What is the relationship between the two statements?', '["Statement I is the cause and Statement II is its effect", "Statement II is the cause and Statement I is its effect", "Both statements are effects of a common cause", "The two statements are not causally related"]', 3, 'There is no plausible link between a restaurant opening and gold prices.', '{"0": "A restaurant cannot move gold prices.", "1": "Gold prices do not make cricketers open restaurants.", "2": "No single cause explains both."}'),
  ('LR-0210', 'Logical Reasoning', 'Cause and effect', 'Cause and effect pairs', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.6', 'Statement I: The college introduced weekly tests.
Statement II: Students began revising more regularly.
What is the relationship between the two statements?', '["Statement I is the cause and Statement II is its effect", "Statement II is the cause and Statement I is its effect", "Both statements are effects of a common cause", "The two statements are not causally related"]', 0, 'Regular tests push students to revise regularly, so I causes II.', '{"1": "Students revising did not introduce the tests.", "2": "The tests themselves are the cause.", "3": "They are linked."}'),
  ('LR-0211', 'Logical Reasoning', 'Cause and effect', 'Cause and effect pairs', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.6', 'Statement I: Mosquito-borne diseases increased in the town.
Statement II: Stagnant water collected in many places after the floods.
What is the relationship between the two statements?', '["Statement I is the cause and Statement II is its effect", "Statement II is the cause and Statement I is its effect", "Both statements are effects of a common cause", "The two statements are not causally related"]', 1, 'Stagnant water lets mosquitoes breed, raising diseases. II causes I.', '{"0": "Diseases do not create stagnant water.", "2": "Stagnant water is itself the cause here.", "3": "They are linked through mosquito breeding."}'),
  ('LR-0212', 'Logical Reasoning', 'Cause and effect', 'Cause and effect pairs', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.6', 'Statement I: Sales of warm clothes rose sharply in the city.
Statement II: Demand for gas heaters increased.
What is the relationship between the two statements?', '["Statement I is the cause and Statement II is its effect", "Statement II is the cause and Statement I is its effect", "Both statements are effects of a common cause", "The two statements are not causally related"]', 2, 'Both are effects of a common cause: an unusually cold winter.', '{"0": "Buying warm clothes does not make people buy heaters.", "1": "Buying heaters does not make people buy warm clothes.", "3": "They share a clear cause."}'),
  ('LR-0213', 'Logical Reasoning', 'Cause and effect', 'Cause and effect pairs', 'easy', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.6', 'Statement I: The farmer used a better variety of seeds.
Statement II: The wheat harvest was much bigger than last year.
What is the relationship between the two statements?', '["Statement I is the cause and Statement II is its effect", "Statement II is the cause and Statement I is its effect", "Both statements are effects of a common cause", "The two statements are not causally related"]', 0, 'Better seeds give higher yields, so I causes II.', '{"1": "A bigger harvest does not change the seeds already sown.", "2": "The seeds are the direct cause.", "3": "They are linked."}'),
  ('LR-0214', 'Logical Reasoning', 'Cause and effect', 'Giving reasons for events', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.6', 'Fewer people in a village fell ill with diarrhoea after a new water filtration plant was installed.
What is the most likely reason?', '["People stopped eating vegetables", "The village population grew", "Cleaner drinking water reduced infections", "The weather became hotter"]', 2, 'Diarrhoea is often spread through contaminated water, so cleaner water is the most likely reason.', '{"0": "Nothing suggests a change in diet.", "1": "A larger population would not reduce illness.", "3": "Hot weather usually increases such illness."}'),
  ('LR-0215', 'Logical Reasoning', 'Cause and effect', 'Rejecting false beliefs', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.6', '"Children who own more books get better marks, so buying books will raise any child''s marks."
What is the main flaw?', '["Books are too expensive", "Marks cannot be measured", "Children do not like books", "Other factors, such as family support, may explain both"]', 3, 'Owning books and getting good marks may both result from a supportive home, so buying books alone may not help.', '{"0": "Cost is not the logical flaw.", "1": "Marks can be measured.", "2": "This is an unsupported generalisation, not the flaw."}'),
  ('LR-0216', 'Logical Reasoning', 'Cause and effect', 'Common causes', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.6', 'In a town, the number of mosques and the number of shops both rose over twenty years.
What is the best explanation?', '["The town''s population grew", "Building mosques creates shops", "Shops lead people to build mosques", "It is a coincidence with no explanation"]', 0, 'A growing population needs both more places of worship and more shops, so population growth is a common cause.', '{"1": "Mosques do not directly cause shops to open.", "2": "Shops do not directly cause mosques to be built.", "3": "A clear common cause explains both."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT INTO question_counters (prefix, n) VALUES ('ENG', 473) ON CONFLICT (prefix) DO UPDATE SET n = max(n, 473);
INSERT INTO question_counters (prefix, n) VALUES ('LR', 216) ON CONFLICT (prefix) DO UPDATE SET n = max(n, 216);

-- English in the AKU bank (every question) and the NUMS bank (all but the literary ones), under the same chapter.
INSERT OR IGNORE INTO bank_questions (bank, question_id, subject, chapter)
SELECT 'aku', q.id, 'English', q.chapter FROM questions q
WHERE q.id BETWEEN 'ENG-0296' AND 'ENG-0473' AND q.source LIKE 'Markhor Prep original question.%';
INSERT OR IGNORE INTO bank_questions (bank, question_id, subject, chapter)
SELECT 'nums', q.id, 'English', q.chapter FROM questions q
WHERE q.id BETWEEN 'ENG-0296' AND 'ENG-0473' AND q.source LIKE 'Markhor Prep original question.%'
  AND q.id NOT IN ('ENG-0335', 'ENG-0336', 'ENG-0337', 'ENG-0338', 'ENG-0339');
